package com.modelpopout;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.Executor;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;

/** EDT-owned FIFO: one worker and at most one pending supplier per open inspector. */
final class InspectionRenderScheduler
{
    interface Work
    {
        void render();
        void failed(Throwable failure);
        void complete();
    }

    private final Executor worker, edt;
    private final Map<Object,Supplier<Work>> waiting = new LinkedHashMap<>();
    private boolean busy, closed;

    InspectionRenderScheduler(Executor worker, Executor edt) { this.worker = worker; this.edt = edt; }

    void request(Object owner, Supplier<Work> work)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (closed) return;
        waiting.put(owner,work); // Replacing pending work does not move it ahead of other windows.
        pump();
    }

    void remove(Object owner) { waiting.remove(owner); }
    void close() { closed = true; waiting.clear(); }
    int queued() { return waiting.size(); }
    boolean busy() { return busy; }

    private void pump()
    {
        if (busy || closed) return;
        while (!waiting.isEmpty())
        {
            Object owner = waiting.keySet().iterator().next();
            Work work = waiting.remove(owner).get();
            if (work == null) continue;
            busy = true;
            try
            {
                worker.execute(() -> {
                    try { work.render(); }
                    catch (Throwable failure) { work.failed(failure); }
                    finally { edt.execute(() -> finish(work)); }
                });
            }
            catch (java.util.concurrent.RejectedExecutionException failure)
            { work.failed(failure); finish(work); }
            return;
        }
    }

    private void finish(Work work)
    {
        try { work.complete(); }
        finally { busy = false; pump(); }
    }
}

package com.modelpopout;

import java.awt.Dimension;
import java.awt.Frame;
import java.awt.Graphics2D;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.awt.image.BufferedImage;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** EDT-owned independent camera/presentation. Frozen snapshots remain renderable after logout. */
final class InspectionSession
{
    private static final Logger LOG=LoggerFactory.getLogger(InspectionSession.class);
    final LiveViewState state=new LiveViewState();
    final InspectionPanel panel;
    private final InspectionRenderScheduler scheduler;
    private final ModelPopoutConfig config;
    private final FramePacer pacer=new FramePacer();
    private final TextureClock clock=new TextureClock();
    private final Timer wake=new Timer(1,event -> requestRender());
    private final Runnable onClose;
    private final java.util.function.Consumer<Boolean> visibility;
    private ViewerWindow window;
    private boolean closed, visible=true, live=true;
    private long hudKey=-1;
    private int npcDefinition=-1;

    InspectionSession(ModelPopoutConfig config, InspectionRenderScheduler scheduler,
        Runnable onClose, java.util.function.Consumer<Boolean> visibility)
    {
        assert SwingUtilities.isEventDispatchThread();
        this.config=config;this.scheduler=scheduler;this.onClose=onClose;this.visibility=visibility;
        panel=new InspectionPanel(config,state,this::requestRender);
        wake.setRepeats(false);pacer.setTarget(config.renderTarget());
    }

    void open(String name)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (closed) return;
        ViewerWindow frame=ViewerWindow.create();window=frame;
        frame.setTitle("Popout — "+name);
        frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        frame.setResizable(true);frame.add(panel,java.awt.BorderLayout.CENTER);
        frame.setModelPainter(g -> {
            Graphics2D child=(Graphics2D)g.create(panel.getX(),panel.getY(),panel.getWidth(),panel.getHeight());
            try { panel.paintModels(child); }
            finally { child.dispose(); }
        });
        frame.addWindowListener(new WindowAdapter()
        { @Override public void windowClosed(WindowEvent event) { close(); } });
        frame.addWindowStateListener(event -> setVisible((event.getNewState() & Frame.ICONIFIED)==0));
        frame.installHoverControls();frame.applyBackgroundOpacity(config.backgroundOpacity());
        frame.applyAlwaysOnTop(config.alwaysOnTop());frame.setMinimumSize(new Dimension(300,300));
        frame.pack();frame.setLocationByPlatform(true);frame.setVisible(true);
    }

    void accept(InspectionCapture.Packet packet)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (closed) return;
        live=packet.live;
        boolean hudIdentityChanged=packet.hud!=null && packet.hud.player.key!=hudKey;
        if (packet.model!=null)
        {
            if (npcDefinition>=0 && packet.npcDefinition>=0 && npcDefinition!=packet.npcDefinition)
            { state.reframeModel(packet.model);panel.anchor=null; }
            else state.updateModel(packet.model,hudIdentityChanged);
            npcDefinition=packet.npcDefinition;
        }
        state.updateTextures(packet.textures);
        if (packet.model!=null) clock.observe(packet.cycle,packet.observedAt);
        if (!live && packet.model!=null) state.setTexturePhase(packet.cycle);
        HudSnapshot previousHud=panel.hud;
        String previousStatus=panel.status;
        panel.hud=visible && live?packet.hud:null;
        hudKey=packet.hud==null?-1:packet.hud.player.key;
        panel.status=live?(packet.model==null?"Waiting for the actor's model…":null)
            :packet.model==null?"Actor unavailable — no model captured":"Actor unavailable — last captured model";
        if (!java.util.Objects.equals(previousStatus,panel.status)
            || (previousHud!=panel.hud && (config.showHitsplats() || config.showHpBars()))) panel.repaint();
        requestRender();
    }

    void settingsChanged()
    {
        if (closed) return;
        pacer.setTarget(config.renderTarget());
        if (window!=null)
        { window.applyWindowControls();window.applyBackgroundOpacity(config.backgroundOpacity());window.applyAlwaysOnTop(config.alwaysOnTop()); }
        panel.repaint();requestRender();
    }

    void setVisible(boolean value)
    {
        if (closed || visible==value) return;
        visible=value;panel.hud=null;
        if (!visible) { wake.stop();scheduler.remove(this); }
        visibility.accept(value);
        if (visible) requestRender();
    }

    void requestRender()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (closed || !visible) return;
        long now=System.nanoTime();
        if (live && state.hasAnimatedTextures()) state.setTexturePhase(clock.phase(now));
        if (!state.needsRender())
        {
            if (live && state.hasAnimatedTextures() && clock.advancing(now)) schedule(now);
            return;
        }
        if (pacer.renderDelay(now)>0) { schedule(now);return; }
        scheduler.request(this,this::begin);
    }

    private void schedule(long now)
    { wake.setInitialDelay(FramePacer.delayMillis(pacer.renderDelay(now)));wake.restart(); }

    private InspectionRenderScheduler.Work begin()
    {
        if (closed || !visible) return null;
        LiveViewState.RenderRequest request=state.begin();
        if (request==null) return null;
        pacer.rendered(System.nanoTime());
        long capturedHudKey=hudKey;
        return new InspectionRenderScheduler.Work()
        {
            private BufferedImage image;
            private Throwable failure;
            @Override public void render() { image=new ModelRenderer().renderScene(request); }
            @Override public void failed(Throwable error) { failure=error; }
            @Override public void complete()
            {
                boolean valid=state.finish(request);
                if (closed) return;
                if (failure!=null) LOG.debug("Unable to render inspected model",failure);
                else if (valid)
                {
                    if (panel.anchor==null) panel.anchor=HudAnchor.initial(request.model,request.framing);
                    panel.image=image;panel.imageCamera=request.camera;panel.imageHudKey=capturedHudKey;
                    panel.repaint();pacer.presented(System.nanoTime());
                }
                requestRender();
            }
        };
    }

    void close()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (closed) return;
        closed=true;visible=false;wake.stop();scheduler.remove(this);
        state.clear();clock.clear();panel.clear();
        if (window!=null)
        {
            window.setModelPainter(g -> {});
            window.dispose();window=null;
        }
        onClose.run();
    }

    boolean closed() { return closed; }
}

package com.modelpopout;

import java.util.concurrent.Executor;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

/** One replaceable packet and at most one queued/running EDT delivery, including racing offers. */
final class LatestHudMailbox
{
    private final AtomicReference<HudSnapshot> latest = new AtomicReference<>();
    private final AtomicBoolean queued = new AtomicBoolean();
    private final Executor dispatch;
    private final Consumer<HudSnapshot> receive;

    LatestHudMailbox(Executor dispatch, Consumer<HudSnapshot> receive)
    {
        this.dispatch = dispatch;
        this.receive = receive;
    }

    void offer(HudSnapshot packet)
    {
        latest.set(packet);
        schedule();
    }

    void clear()
    {
        latest.set(null);
    }

    private void schedule()
    {
        if (queued.compareAndSet(false, true)) dispatch.execute(this::drain);
    }

    private void drain()
    {
        try
        {
            HudSnapshot packet = latest.getAndSet(null);
            if (packet != null) receive.accept(packet);
        }
        finally
        {
            queued.set(false);
            if (latest.get() != null) schedule();
        }
    }
}

package com.modelpopout;

/** Short synchronized operations shared by the client thread and Swing EDT. */
final class LiveCaptureGate
{
    private long epoch;
    private boolean open, loggedIn, pending, scheduled;
    private long nextDue;
    private int fps = 20;

    synchronized void setRate(int fps)
    {
        this.fps = Math.max(1, Math.min(50, fps));
        scheduled = false;
    }

    synchronized long open()
    {
        open = true;
        invalidate();
        return epoch;
    }

    synchronized void close()
    {
        open = false;
        invalidate();
    }

    synchronized long setLoggedIn(boolean value)
    {
        if (loggedIn != value)
        {
            loggedIn = value;
            invalidate();
        }
        return epoch;
    }

    private void invalidate()
    {
        epoch++;
        pending = false;
        scheduled = false;
    }

    /** Returns a lifecycle ticket, or -1 if throttled, inactive, or awaiting an EDT handoff. */
    synchronized long acquire(long now)
    {
        if (!open || !loggedIn || pending) return -1;
        if (scheduled && now - nextDue < 0) return -1;
        long period = 1_000_000_000L / fps;
        if (!scheduled)
        {
            nextDue = now + period;
        }
        else
        {
            // Keep fractional tick timing at 20 FPS (50ms) on a 20ms tick cadence.
            // Skip missed deadlines rather than scheduling catch-up captures.
            nextDue = now + period - (now - nextDue) % period;
        }
        scheduled = true;
        pending = true;
        return epoch;
    }

    synchronized boolean complete(long ticket)
    {
        if (ticket != epoch || !open || !loggedIn) return false;
        pending = false;
        return true;
    }

    synchronized boolean current(long ticket)
    {
        return open && ticket == epoch;
    }

    synchronized boolean viewing()
    {
        return open;
    }

    synchronized boolean active()
    {
        return open && loggedIn;
    }

    synchronized long epoch()
    {
        return epoch;
    }
}

package com.modelpopout;

/** EDT-confined latest model/view state: one active render and one replaceable latest request. */
final class LiveViewState
{
    private ModelSnapshot model;
    private TextureSet textures = TextureSet.EMPTY;
    private double texturePhase;
    private ModelFrame framing;
    private ModelSnapshot npcModel;
    private ModelFrame npcFraming;
    private long npcKey = -1, sceneSession;
    private boolean npcEnabled;
    private CameraView camera = CameraView.DEFAULT;
    private long revision, modelSession, attemptedRevision = -1;
    private RenderRequest active;

    boolean updateModel(ModelSnapshot next, boolean force)
    {
        if (!force && next.sameAppearance(model)) return false;
        if (framing == null) framing = ModelFrame.initial(next);
        model = next;
        revision++;
        return true;
    }

    boolean updateNpc(ModelSnapshot next, long key)
    {
        if (!npcEnabled) { next = null; key = -1; }
        boolean identityChanged = key != npcKey;
        boolean visibilityChanged = (next != null) != (npcModel != null);
        if (!identityChanged && !visibilityChanged && (next == null || next.sameAppearance(npcModel))) return false;
        if (identityChanged || visibilityChanged) sceneSession++;
        if (identityChanged) npcFraming = null;
        if (next != null && npcFraming == null) npcFraming = ModelFrame.initial(next);
        npcKey = key;
        npcModel = next;
        revision++;
        return true;
    }

    /** Inspector-only semantic transformation: refit once, retaining the user's camera and worker slot. */
    void reframeModel(ModelSnapshot next)
    {
        modelSession++;
        framing=null;
        updateModel(next,true);
    }

    boolean removeNpc(long key)
    {
        return npcKey == key && updateNpc(null, -1);
    }

    void setNpcEnabled(boolean enabled)
    {
        if (npcEnabled == enabled) return;
        npcEnabled = enabled;
        if (!enabled) { npcModel = null; npcFraming = null; npcKey = -1; }
        sceneSession++;
        revision++;
    }

    boolean npcEnabled() { return npcEnabled; }
    boolean hasNpc() { return npcEnabled && npcModel != null; }
    long npcKey() { return npcKey; }

    CameraView camera()
    {
        return camera;
    }

    void setCamera(CameraView next)
    {
        if (camera.yaw == next.yaw && camera.pitch == next.pitch && camera.zoom == next.zoom) return;
        camera = next;
        revision++;
    }

    boolean updateTextures(TextureSet next)
    {
        if (next.samePixels(textures)) return false;
        textures = next;
        revision++;
        return true;
    }

    boolean hasAnimatedTextures() { return textures.animated(); }

    void setTexturePhase(double phase)
    {
        double quantized = Math.floor(phase*1024)/1024;
        if (textures.animated() && quantized != texturePhase) { texturePhase = quantized; revision++; }
    }

    boolean needsRender() { return active == null && model != null && revision != attemptedRevision; }

    RenderRequest begin()
    {
        if (active != null || model == null || revision == attemptedRevision) return null;
        active = new RenderRequest(model, camera, framing, revision, modelSession,
            npcEnabled, npcModel, npcFraming, npcKey, sceneSession,textures,texturePhase);
        return active;
    }

    boolean finish(RenderRequest request)
    {
        if (active != request) return false;
        active = null;
        attemptedRevision = request.revision;
        return valid(request);
    }

    boolean valid(RenderRequest request)
    {
        return request.modelSession == modelSession && request.sceneSession == sceneSession;
    }

    void clear()
    {
        model = null;
        textures = TextureSet.EMPTY;
        texturePhase = 0;
        npcModel = null; npcFraming = null; npcKey = -1;
        sceneSession++;
        modelSession++;
        revision++;
        // Keep the active slot occupied until the real worker ends, including across close/reopen.
    }

    void resetFraming()
    {
        clear();
        framing = null;
    }

    static final class RenderRequest
    {
        final TextureSet textures;
        final double texturePhase;
        final ModelSnapshot model;
        final CameraView camera;
        final ModelFrame framing, npcFraming;
        final ModelSnapshot npcModel;
        final boolean npcEnabled;
        final long npcKey;
        private final long revision, modelSession, sceneSession;
        private RenderRequest(ModelSnapshot model, CameraView camera, ModelFrame framing, long revision, long modelSession,
            boolean npcEnabled, ModelSnapshot npcModel, ModelFrame npcFraming, long npcKey, long sceneSession,TextureSet textures,double texturePhase)
        {
            this.textures = textures; this.texturePhase = texturePhase;
            this.model = model;
            this.camera = camera;
            this.framing = framing;
            this.revision = revision;
            this.modelSession = modelSession;
            this.npcEnabled = npcEnabled; this.npcModel = npcModel; this.npcFraming = npcFraming;
            this.npcKey = npcKey; this.sceneSession = sceneSession;
        }
    }
}

package com.modelpopout;

/** Immutable model-space framing, established once and independent of animation pose. */
final class ModelFrame
{
    // Reserve motion space even when the first sample is a crouched/compact pose.
    private static final double MIN_ANIMATION_RADIUS = 256;
    private static final double ANIMATION_HEADROOM = 2;
    final double centerX, centerY, centerZ, radius;

    private ModelFrame(double centerX, double centerY, double centerZ, double radius)
    {
        this.centerX = centerX;
        this.centerY = centerY;
        this.centerZ = centerZ;
        this.radius = radius;
    }

    static ModelFrame initial(ModelSnapshot mesh)
    {
        ModelFrame fitted = fit(mesh);
        return new ModelFrame(fitted.centerX, fitted.centerY, fitted.centerZ,
            Math.max(MIN_ANIMATION_RADIUS, fitted.radius * ANIMATION_HEADROOM));
    }

    /** Tight framing for isolated static renderer tests; live frames use initial() once. */
    static ModelFrame fit(ModelSnapshot mesh)
    {
        double minX = Double.POSITIVE_INFINITY, minY = minX, minZ = minX;
        double maxX = Double.NEGATIVE_INFINITY, maxY = maxX, maxZ = maxX;
        for (int i = 0; i < mesh.x.length; i++)
        {
            minX = Math.min(minX, mesh.x[i]); maxX = Math.max(maxX, mesh.x[i]);
            minY = Math.min(minY, mesh.y[i]); maxY = Math.max(maxY, mesh.y[i]);
            minZ = Math.min(minZ, mesh.z[i]); maxZ = Math.max(maxZ, mesh.z[i]);
        }
        double cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
        double radius = 0;
        for (int i = 0; i < mesh.x.length; i++)
        {
            double x = mesh.x[i] - cx, y = mesh.y[i] - cy, z = mesh.z[i] - cz;
            radius = Math.max(radius, Math.sqrt(x * x + y * y + z * z));
        }
        return new ModelFrame(cx, cy, cz, Math.max(.5, radius));
    }

    double scale(CameraView camera)
    {
        return (ModelRenderer.SIZE - 48) / (2 * radius) * camera.zoom;
    }
}

