package com.modelpopout;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Rectangle;

/** Geometry for invisible native-style resize edges. */
final class WindowGeometry
{
    static final int NORTH = 1, EAST = 2, SOUTH = 4, WEST = 8;
    static final int BORDER = 6;

    // All coordinates are AWT user-space units, including negative monitor origins.
    static Rectangle move(Rectangle start, java.awt.Point pressed, java.awt.Point current)
    {
        return new Rectangle(start.x+current.x-pressed.x,start.y+current.y-pressed.y,start.width,start.height);
    }

    static boolean titleReachable(Rectangle window, Rectangle monitor)
    {
        Rectangle title = new Rectangle(window.x,window.y,window.width,32);
        Rectangle intersection = title.intersection(monitor);
        return intersection.width >= Math.min(window.width,160) && intersection.height >= 26;
    }

    static Rectangle usable(Rectangle monitor, java.awt.Insets insets)
    {
        return new Rectangle(monitor.x+insets.left,monitor.y+insets.top,
            Math.max(1,monitor.width-insets.left-insets.right),
            Math.max(1,monitor.height-insets.top-insets.bottom));
    }

    static int edges(int x, int y, int width, int height)
    {
        int edges = 0;
        if (x < BORDER) edges |= WEST;
        else if (x >= width-BORDER) edges |= EAST;
        if (y < BORDER) edges |= NORTH;
        else if (y >= height-BORDER) edges |= SOUTH;
        return edges;
    }

    static int cursor(int edges)
    {
        switch (edges)
        {
            case NORTH: return Cursor.N_RESIZE_CURSOR;
            case EAST: return Cursor.E_RESIZE_CURSOR;
            case SOUTH: return Cursor.S_RESIZE_CURSOR;
            case WEST: return Cursor.W_RESIZE_CURSOR;
            case NORTH | EAST: return Cursor.NE_RESIZE_CURSOR;
            case NORTH | WEST: return Cursor.NW_RESIZE_CURSOR;
            case SOUTH | EAST: return Cursor.SE_RESIZE_CURSOR;
            case SOUTH | WEST: return Cursor.SW_RESIZE_CURSOR;
            default: return Cursor.DEFAULT_CURSOR;
        }
    }

    static Rectangle resize(Rectangle start, int edges, int dx, int dy, Dimension minimum)
    {
        Rectangle next = new Rectangle(start);
        if ((edges & EAST) != 0) next.width = Math.max(minimum.width,start.width+dx);
        if ((edges & SOUTH) != 0) next.height = Math.max(minimum.height,start.height+dy);
        if ((edges & WEST) != 0)
        {
            next.width = Math.max(minimum.width,start.width-dx);
            next.x = start.x+start.width-next.width;
        }
        if ((edges & NORTH) != 0)
        {
            next.height = Math.max(minimum.height,start.height-dy);
            next.y = start.y+start.height-next.height;
        }
        return next;
    }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;

/** EDT-owned buffer at the native Window.paint boundary, including AWT's background clear. */
final class WindowPresentation
{
    private BufferedImage buffer;
    private final boolean diagnostics = Boolean.getBoolean("modelpopout.paintDiagnostics");
    private String destinationFormat = "unpainted";

    // Read-only trace of the outer border pixel, away from model/HUD content.
    String backgroundArgb()
    {
        return buffer == null ? "unpainted" : String.format("%08x",buffer.getRGB(0,0));
    }

    String destinationFormat() { return destinationFormat; }

    void paint(Graphics graphics, int width, int height, Consumer<Graphics2D> hierarchy)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (width <= 0 || height <= 0) return;
        if (diagnostics && graphics instanceof Graphics2D)
        {
            java.awt.image.ColorModel format = ((Graphics2D)graphics).getDeviceConfiguration().getColorModel();
            destinationFormat = "bits="+format.getPixelSize()+",alpha="+format.hasAlpha();
        }
        if (buffer == null || buffer.getWidth() != width || buffer.getHeight() != height)
            buffer = new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);

        Graphics2D frame = buffer.createGraphics();
        try
        {
            frame.setComposite(AlphaComposite.Clear);
            frame.fillRect(0,0,width,height);
            frame.setComposite(AlphaComposite.SrcOver);
            // Window.paint may clear again. Both that clear and all child paints stay private.
            hierarchy.accept(frame);
        }
        finally { frame.dispose(); }

        Graphics2D target = (Graphics2D) graphics.create();
        try
        {
            target.setComposite(AlphaComposite.Src);
            target.drawImage(buffer,0,0,null);
        }
        finally { target.dispose(); }
    }
}

package com.modelpopout;

import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/** Apply only to the viewer's Window; a rejected desktop request must not disrupt rendering. */
final class WindowStacking
{
    static boolean apply(boolean requested, BooleanSupplier supported, Consumer<Boolean> setAlwaysOnTop)
    {
        try
        {
            if (requested && !supported.getAsBoolean()) return false;
            setAlwaysOnTop.accept(requested);
            return true;
        }
        catch (UnsupportedOperationException | SecurityException unavailable)
        {
            return false;
        }
    }
}

package com.modelpopout;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;

/** Ordinary Swing children: every repaint ascends through Surface and WindowPresentation. */
final class WindowTitleBar extends JPanel
{
    interface Actions
    {
        void minimize();
        void maximize();
        void close();
        Rectangle bounds();
        boolean maximized();
        void move(Rectangle bounds);
    }

    final JLabel title = new JLabel("Model Popout");
    final JButton minimize, maximize, close;

    WindowTitleBar(Actions actions)
    {
        super(new BorderLayout());
        setOpaque(true);
        setBackground(new Color(38,38,38));
        title.setForeground(new Color(230,230,230));
        title.setBorder(BorderFactory.createEmptyBorder(0,8,0,8));
        add(title,BorderLayout.CENTER);
        JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.RIGHT,0,0));
        buttons.setOpaque(false);
        minimize = button("−","Minimize",actions::minimize);
        maximize = button("□","Maximize / restore",actions::maximize);
        close = button("×","Close",actions::close);
        buttons.add(minimize);buttons.add(maximize);buttons.add(close);
        add(buttons,BorderLayout.EAST);
        MouseAdapter drag = new MouseAdapter()
        {
            private Point pointer;
            private Rectangle start;
            @Override public void mousePressed(MouseEvent e)
            {
                pointer=null;
                if (!SwingUtilities.isLeftMouseButton(e) || actions.maximized()) return;
                pointer=e.getLocationOnScreen();start=actions.bounds();
            }
            @Override public void mouseDragged(MouseEvent e)
            {
                if (pointer!=null && !actions.maximized())
                    actions.move(WindowGeometry.move(start,pointer,e.getLocationOnScreen()));
            }
            @Override public void mouseReleased(MouseEvent e) { pointer=null; }
            @Override public void mouseClicked(MouseEvent e)
            { if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount()==2) actions.maximize(); }
        };
        // Buttons deliberately do not receive the drag listener.
        addMouseListener(drag);addMouseMotionListener(drag);
        title.addMouseListener(drag);title.addMouseMotionListener(drag);
    }

    private static JButton button(String text,String name,Runnable action)
    {
        JButton button=new JButton(text);
        button.setPreferredSize(new Dimension(32,26));
        button.setMargin(new java.awt.Insets(0,0,0,0));
        button.setToolTipText(name);button.getAccessibleContext().setAccessibleName(name);
        button.addActionListener(e -> action.run());
        return button;
    }
}

package com.modelpopout;

import java.awt.Color;
import java.awt.IllegalComponentStateException;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Native background/configuration recovery only; never applies whole-window opacity. */
final class WindowTransparency
{
    private static final Color TRANSPARENT = new Color(0,0,0,0);

    static boolean apply(boolean available, BooleanSupplier capable, Supplier<Color> background,
        Consumer<Color> setBackground)
    {
        if (available)
        {
            try
            {
                Color current = background.get();
                // AWT negotiates an alpha-capable configuration only on opaque -> translucent.
                // Repeating an already-transparent color is a no-op after a configuration change.
                if (!capable.getAsBoolean() && current != null && current.getAlpha() < 255)
                    setBackground.accept(BackgroundOpacity.color(100));
                setBackground.accept(TRANSPARENT);
                Color applied = background.get();
                if (capable.getAsBoolean() && applied != null && applied.getAlpha() == 0) return true;
            }
            catch (UnsupportedOperationException | IllegalComponentStateException unavailable)
            {
                // A desktop/device can reject translucency despite its advertised capability.
            }
        }
        setBackground.accept(BackgroundOpacity.color(100));
        return false;
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnimatedTextureTest
{
    @Test public void nativeClockDoesNotRunAwayWhenClientLosesFocusOrStopsAdvancing()
    {
        TextureClock clock = new TextureClock();
        clock.observe(100,1000000000L);
        assertEquals(100,clock.phase(1000000000L),0);
        assertEquals(100.5,clock.phase(1010000000L),0);
        assertEquals(101,clock.phase(2000000000L),0);
        assertFalse(clock.advancing(2000000000L));
        clock.observe(100,2000000000L); // Repeated events at the same cycle do not restart free-running motion.
        assertEquals(101,clock.phase(2000000000L),0);
        clock.observe(110,2000000000L);
        assertEquals(110,clock.phase(2000000000L),0);
        clock.clear();
        assertFalse(clock.advancing(3000000000L));
    }

    @Test public void allDirectionsSpeedWrapAndCpuAlreadyScrolledPixelsUseCorrectOffsets()
    {
        int[] pixels=new int[16];
        for(int i=0;i<pixels.length;i++) pixels[i]=0x100000+i+1;
        for(int direction=1;direction<=4;direction++)
        {
            TextureSet.Pixels texture=new TextureSet.Pixels(pixels,direction,1,0,0);
            TextureSet cpu=new TextureSet(Collections.singletonMap(0,texture),50,false);
            assertEquals(0xff000000|pixels[0],texture.sampleArgb(.125,.125,50,cpu));
            int index=direction==1?12:direction==3?4:direction==2?3:1;
            int moved=texture.sampleArgb(.125,.125,51,cpu);
            assertEquals(0xff000000|pixels[index],moved);
            assertEquals(0xff000000|pixels[0],texture.sampleArgb(.125,.125,54,cpu));
            TextureSet gpu=new TextureSet(cpu.textures,50,true);
            assertEquals(moved,texture.sampleArgb(.125,.125,32,gpu)); // One texel of a 4px fixture in GPU's 128-unit clock.
        }
        TextureSet.Pixels fast=new TextureSet.Pixels(pixels,4,2,0,0);
        TextureSet cpu=new TextureSet(Collections.singletonMap(0,fast),0,false);
        assertEquals(0xff000000|pixels[1],fast.sampleArgb(.125,.125,.5,cpu));
    }

    @Test public void fractionalAnimationFiltersRealTexelsAndRetainsCutoutAlpha()
    {
        TextureSet.Pixels texture=new TextureSet.Pixels(new int[]{0xff0000,0,0xff0000,0},4,1,0,0);
        TextureSet set=new TextureSet(Collections.singletonMap(0,texture),0,false);
        int halfway=texture.sampleArgb(.25,.25,.5,set);
        assertEquals(128,halfway>>>24);
        assertEquals(0xff0000,halfway&0xffffff);
        assertEquals(0,texture.sampleArgb(.25,.25,1,set));
    }

    @Test public void uniformTexturesDoNotScheduleDuplicateAnimationFrames()
    {
        TextureSet set = new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(new int[]{0xff0000},1,1,0,0)),0,true);
        assertFalse(set.animated());
    }

    @Test public void cachedAndUncachedRasterizationAgreeIncludingCutoutsAndCoincidentFaces()
    {
        TextureRenderingTest.TexturedModel nativeModel = new TextureRenderingTest.TexturedModel()
        {
            @Override public int getFaceCount() { return 2; }
            @Override public int[] getFaceIndices1() { return new int[]{0,0}; }
            @Override public int[] getFaceIndices2() { return new int[]{2,2}; }
            @Override public int[] getFaceIndices3() { return new int[]{1,1}; }
            @Override public int[] getFaceColors1() { return new int[]{127,20000}; }
            @Override public int[] getFaceColors2() { return getFaceColors1(); }
            @Override public int[] getFaceColors3() { return getFaceColors1(); }
            @Override public short[] getFaceTextures() { return new short[]{0,-1}; }
            @Override public byte[] getFaceTransparencies() { return new byte[]{0,0}; }
            @Override public byte[] getTextureFaces() { return new byte[]{-1,-1}; }
        };
        ModelSnapshot mesh = ModelSnapshot.capture(nativeModel,null).toRgb();
        CameraView camera = new CameraView(0,0,1);ModelFrame frame = ModelFrame.initial(mesh);
        ModelProjection projection = mesh.projection(camera,frame);
        TextureRasterPlan plan = projection.rasterPlan(mesh);
        assertNotNull(plan);
        ModelRenderer renderer = new ModelRenderer();
        for (int[] pixels : new int[][]{{0xff0000,0x00ff00,0x0000ff,0xffffff},{0xff0000,0,0,0xffffff}})
        {
            TextureSet set = new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(pixels,2,1,0,0)),0,false);
            for (double phase : new double[]{0,.25,.5,1})
            {
                BufferedImage cached = plan.render(set,phase);
                BufferedImage plain = renderer.rasterize(mesh,projection,set,phase);
                assertArrayEquals(plain.getRGB(0,0,512,512,null,0,512),cached.getRGB(0,0,512,512,null,0,512));
            }
        }
    }

    @Test public void animatedTextureFramesReuseTheCapturedPoseProjectionAndRasterPlan()
    {
        ModelSnapshot mesh=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel(),null);
        CameraView camera=new CameraView(0,0,1);ModelFrame frame=ModelFrame.initial(mesh);
        int[] pixels={0xff0000,0x00ff00,0x0000ff,0xffffff};
        TextureSet set=new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(pixels,2,1,0,0)),0,false);
        ModelRenderer renderer=new ModelRenderer();
        BufferedImage first=renderer.render(mesh,camera,frame,set,0);
        ModelProjection projection=mesh.toRgb().projection(camera,frame);
        TextureRasterPlan plan=projection.rasterPlan(mesh.toRgb());
        assertNotNull(plan);
        assertTrue(plan.fragments() > 0 && plan.fragments() <= TextureRasterPlan.MAX_FRAGMENTS);
        int[] old=first.getRGB(0,0,512,512,null,0,512);
        BufferedImage later=renderer.render(mesh,camera,frame,set,.5);
        assertFalse(Arrays.equals(old,later.getRGB(0,0,512,512,null,0,512)));
        assertSame(projection,mesh.toRgb().projection(camera,frame));
        assertSame(plan,projection.rasterPlan(mesh.toRgb()));
        assertArrayEquals(old,first.getRGB(0,0,512,512,null,0,512));
        assertSame(later,renderer.render(mesh,camera,frame,set,.5));
    }

    @Test public void texturesAdvanceEvenWithoutNewGeometryAndLifecycleClearInvalidatesOldFrames()
    {
        ModelSnapshot mesh=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel(),null);
        TextureSet textures=new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(new int[]{0xff0000,0x00ff00,0x0000ff,0xffffff},1,1,0,0)),0,true);
        LiveViewState state=new LiveViewState();state.updateModel(mesh,false);state.updateTextures(textures);
        state.setTexturePhase(50);LiveViewState.RenderRequest first=state.begin();state.finish(first);
        assertFalse(state.updateModel(mesh,false));state.setTexturePhase(50.5);
        LiveViewState.RenderRequest next=state.begin();
        assertSame(first.model,next.model);assertSame(first.framing,next.framing);
        assertEquals(50.5,next.texturePhase,0);
        state.clear();assertFalse(state.finish(next));assertFalse(state.hasAnimatedTextures());assertNull(state.begin());
    }
}

