        assertTrue(colorPixels(renderer.renderStatic(mesh, new CameraView(0, CameraView.MAX_PITCH, 1)), 0xff00ff) > 100);
        assertTrue(colorPixels(renderer.renderStatic(mesh, new CameraView(0, CameraView.MIN_PITCH, 1)), 0x00ffff) > 100);
    }

    @Test public void zoomChangesProjectedSizeWithoutChangingMeshOrCamera()
    {
        ModelSnapshot mesh = box();
        float[] originalX = mesh.x.clone(), originalY = mesh.y.clone(), originalZ = mesh.z.clone();
        int[] originalFaces = mesh.a.clone();
        CameraView view = new CameraView(Math.PI / 2, .2, 1);
        ModelRenderer renderer = new ModelRenderer();
        int small = visiblePixels(renderer.renderStatic(mesh, new CameraView(view.yaw, view.pitch, .5)));
        int large = visiblePixels(renderer.renderStatic(mesh, view));
        assertTrue(large > small * 3);
        assertArrayEquals(originalX, mesh.x, 0);
        assertArrayEquals(originalY, mesh.y, 0);
        assertArrayEquals(originalZ, mesh.z, 0);
        assertArrayEquals(originalFaces, mesh.a);
        // Rendering a fresh capture uses the selected camera without resetting it.
        assertArrayEquals(pixels(renderer.renderStatic(mesh, view)), pixels(renderer.renderStatic(box(), view)));
        assertEquals(Math.PI / 2, view.yaw, 1e-12);
        assertEquals(.2, view.pitch, 0);
    }

    @Test public void fullTurnReturnsSameImageAndProjectionStaysCentered()
    {
        ModelRenderer renderer = new ModelRenderer();
        ModelSnapshot mesh = box();
        assertArrayEquals(pixels(renderer.renderStatic(mesh, new CameraView(0, 0, 1))),
            pixels(renderer.renderStatic(mesh, new CameraView(Math.PI * 2, 0, 1))));
        for (int i = 0; i < 8; i++)
        {
            BufferedImage image = renderer.renderStatic(mesh, new CameraView(i * Math.PI / 4, .3, 1));
            int minX = 512, minY = 512, maxX = -1, maxY = -1;
            for (int y = 0; y < 512; y++) for (int x = 0; x < 512; x++)
            {
                if ((image.getRGB(x, y) & 0xffffff) == ModelRenderer.BACKGROUND) continue;
                minX = Math.min(minX, x); maxX = Math.max(maxX, x);
                minY = Math.min(minY, y); maxY = Math.max(maxY, y);
            }
            assertEquals(511, minX + maxX, 1);
            assertEquals(511, minY + maxY, 1);
        }
    }

    @Test public void protrudingEquipmentGeometryRemainsVisibleAcrossOrbit()
    {
        ModelSnapshot body = box();
        float[] x = Arrays.copyOf(body.x, 17), y = Arrays.copyOf(body.y, 17), z = Arrays.copyOf(body.z, 17);
        float[] gearX = {-90, -90, -50, 55, 100, 55, -45, 45, 0};
        float[] gearY = {-90, 100, 0, -60, 0, 60, -90, -90, 115};
        float[] gearZ = {-10, -10, -10, -35, -35, -35, 50, 50, 50};
        System.arraycopy(gearX, 0, x, 8, 9);
        System.arraycopy(gearY, 0, y, 8, 9);
        System.arraycopy(gearZ, 0, z, 8, 9);
        int[] a = Arrays.copyOf(body.a, 15), b = Arrays.copyOf(body.b, 15), c = Arrays.copyOf(body.c, 15);
        int[] colors = Arrays.copyOf(body.colorA, 15);
        int[] gearColors = {0xaaaaaa, 0x8844cc, 0x44aa88};
        for (int i = 0; i < 3; i++)
        {
            a[12 + i] = 8 + i * 3; b[12 + i] = 9 + i * 3; c[12 + i] = 10 + i * 3;
            colors[12 + i] = gearColors[i];
        }
        // Stand-ins for protruding weapon, shield, and rear cape geometry, used only in this test.
        ModelSnapshot equipped = new ModelSnapshot(x, y, z, a, b, c, colors, colors, colors, new byte[15]);
        boolean[] seen = new boolean[3];
        ModelRenderer renderer = new ModelRenderer();
        for (int i = 0; i < 16; i++)
        {
            BufferedImage image = renderer.renderStatic(equipped, new CameraView(i * Math.PI / 8, .2, 1));
            for (int gear = 0; gear < 3; gear++) seen[gear] |= colorPixels(image, gearColors[gear]) > 100;
            for (int edge = 0; edge < 512; edge++)
            {
                assertEquals(ModelRenderer.BACKGROUND, image.getRGB(edge, 0) & 0xffffff);
                assertEquals(ModelRenderer.BACKGROUND, image.getRGB(edge, 511) & 0xffffff);
                assertEquals(ModelRenderer.BACKGROUND, image.getRGB(0, edge) & 0xffffff);
                assertEquals(ModelRenderer.BACKGROUND, image.getRGB(511, edge) & 0xffffff);
            }
        }
        assertTrue("Weapon geometry visible", seen[0]);
        assertTrue("Shield geometry visible", seen[1]);
        assertTrue("Cape geometry visible", seen[2]);
    }

    private static int[] pixels(BufferedImage image)
    {
        return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
    }

    private static int visiblePixels(BufferedImage image)
    {
        return (int) Arrays.stream(pixels(image)).filter(p -> (p & 0xffffff) != ModelRenderer.BACKGROUND).count();
    }

    private static long colorPixels(BufferedImage image, int color)
    {
        return Arrays.stream(pixels(image)).filter(p -> (p & 0xffffff) == color).count();
    }

    private static void assertColor(int expected, int actual)
    {
        for (int shift = 0; shift <= 16; shift += 8)
        {
            assertEquals((expected >> shift) & 255, (actual >> shift) & 255, 1);
        }
    }
}

package com.modelpopout;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

/** Explicit test-data parsing: no reflection or private snapshot deserialization. */
final class CapeFixtureReader
{
    @SuppressWarnings("deprecation")
    static CapeSurfaceTest.Fixture read(String source)
    {
        JsonObject root=new JsonParser().parse(source).getAsJsonObject();
        JsonObject mesh=root.getAsJsonObject("mesh");
        CapeSurfaceTest.Fixture fixture=new CapeSurfaceTest.Fixture();
        fixture.pixels=ints(root,"pixels");
        fixture.textureId=root.get("textureId").getAsInt();
        fixture.direction=root.get("direction").getAsInt();
        fixture.speed=root.get("speed").getAsInt();
        int[] assignments=ints(mesh,"textureIds");
        TestModel model=new TestModel()
        {
            public int getVerticesCount(){return mesh.getAsJsonArray("x").size();}
            public int getFaceCount(){return mesh.getAsJsonArray("a").size();}
            public float[] getVerticesX(){return floats(mesh,"x");}
            public float[] getVerticesY(){return floats(mesh,"y");}
            public float[] getVerticesZ(){return floats(mesh,"z");}
            public int[] getFaceIndices1(){return ints(mesh,"a");}
            public int[] getFaceIndices2(){return ints(mesh,"b");}
            public int[] getFaceIndices3(){return ints(mesh,"c");}
            public int[] getFaceColors1(){return colors(mesh,"colorA","lightA",assignments);}
            public int[] getFaceColors2(){return colors(mesh,"colorB","lightB",assignments);}
            public int[] getFaceColors3(){return colors(mesh,"colorC","lightC",assignments);}
            public short[] getFaceTextures(){return shorts(assignments);}
            public byte[] getFaceTransparencies(){return bytes(ints(mesh,"alpha"));}
            public byte[] getTextureFaces(){return bytes(ints(mesh,"textureFaces"));}
            public byte[] getFaceRenderPriorities(){return bytes(ints(mesh,"priorities"));}
            public int[] getTexIndices1(){return ints(mesh,"texA");}
            public int[] getTexIndices2(){return ints(mesh,"texB");}
            public int[] getTexIndices3(){return ints(mesh,"texC");}
        };
        fixture.mesh=ModelSnapshot.capture(model,null);
        return fixture;
    }
    private static int[] colors(JsonObject mesh,String color,String light,int[] assignments)
    {
        int[] values=ints(mesh,color),lights=ints(mesh,light);
        for(int i=0;i<values.length;i++) if(assignments[i]>=0) values[i]=lights[i];
        return values;
    }
    private static int[] ints(JsonObject root,String name)
    {
        JsonElement element=root.get(name);
        if(element==null || element.isJsonNull()) return null;
        JsonArray array=element.getAsJsonArray();int[] values=new int[array.size()];
        for(int i=0;i<values.length;i++) values[i]=array.get(i).getAsInt();
        return values;
    }
    private static float[] floats(JsonObject root,String name)
    {
        JsonArray array=root.getAsJsonArray(name);float[] values=new float[array.size()];
        for(int i=0;i<values.length;i++) values[i]=array.get(i).getAsFloat();
        return values;
    }
    private static short[] shorts(int[] values)
    {
        if(values==null) return null;
        short[] result=new short[values.length];
        for(int i=0;i<values.length;i++) result[i]=(short)values[i];
        return result;
    }
    private static byte[] bytes(int[] values)
    {
        if(values==null) return null;
        byte[] result=new byte[values.length];
        for(int i=0;i<values.length;i++) result[i]=(byte)values[i];
        return result;
    }
}

package com.modelpopout;


import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Assume;
import org.junit.Test;
import static org.junit.Assert.*;

/** Opposing cape faces must not compete for the same pixels, including on texture-only frames. */
public class CapeSurfaceTest
{
    private ModelSnapshot cape(boolean hideBack, int transparency, byte priority)
    {
        TextureRenderingTest.TexturedModel model = new TextureRenderingTest.TexturedModel()
        {
            @Override public float[] getVerticesZ(){return new float[]{0,5,11};}
            @Override public int getFaceCount(){return 2;}
            @Override public int[] getFaceIndices1(){return new int[]{0,0};}
            @Override public int[] getFaceIndices2(){return new int[]{2,1};}
            @Override public int[] getFaceIndices3(){return new int[]{1,2};}
            @Override public int[] getFaceColors1(){return new int[]{127,910};}
            @Override public int[] getFaceColors2(){return getFaceColors1();}
            @Override public int[] getFaceColors3(){return getFaceColors1();}
            @Override public short[] getFaceTextures(){return new short[]{0,-1};}
            @Override public byte[] getTextureFaces(){return new byte[]{-1,-1};}
            @Override public byte[] getFaceTransparencies(){return new byte[]{(byte)transparency,hideBack?(byte)255:0};}
            @Override public byte[] getFaceRenderPriorities(){return new byte[]{priority,0};}
        };
        return ModelSnapshot.capture(model,null).toRgb();
    }

    private static int[] pixels(BufferedImage image)
    { return image.getRGB(0,0,512,512,null,0,512); }

    @Test public void reverseCapeFacesNeverContaminateLavaInEitherRasterPath()
    {
        for (byte priority : new byte[]{0,10,11}) for (int alpha : new int[]{0,128})
        {
            ModelSnapshot both=cape(false,alpha,priority),front=cape(true,alpha,priority);
            ModelFrame frame=ModelFrame.fit(both);
            TextureSet textures=new TextureSet(Collections.singletonMap(0,
                new TextureSet.Pixels(new int[]{0xf9b535,0x9c3004,0xffcf61,0x541700},1,2,0,0)),0,false);
            for (double yaw : new double[]{0,.35,.9})
            {
                CameraView camera=new CameraView(yaw,.25,1);
                ModelProjection projection=both.projection(camera,frame);
                TextureRasterPlan plan=projection.rasterPlan(both);
                if(alpha==0)
                {
                    assertNotNull(plan);
                    assertTrue(plan.fragments()>0);
                    assertEquals(front.projection(camera,frame).rasterPlan(front).fragments(),plan.fragments());
                }
                else assertNull(plan); // Exercise the general path's original face alpha blending.
                for(double phase:new double[]{0,.25,.5,1,64})
                {
                    ModelRenderer renderer=new ModelRenderer();
                    int[] expected=pixels(renderer.rasterize(front,front.projection(camera,frame),textures,phase));
                    assertArrayEquals(expected,pixels(renderer.rasterize(both,projection,textures,phase)));
                    assertArrayEquals(expected,pixels(renderer.render(both,camera,frame,textures,phase)));
                    assertTrue(Arrays.stream(expected).anyMatch(p -> (p>>>24)>0));
                }
            }
        }
    }

    @Test public void zeroTexelsDoNotRevealTheCulledRedReverseFace()
    {
        ModelSnapshot both=cape(false,0,(byte)10);
        CameraView camera=new CameraView(0,0,1);ModelFrame frame=ModelFrame.fit(both);
        TextureSet zero=TextureRenderingTest.texture(new int[]{0});
        ModelRenderer renderer=new ModelRenderer();
        assertTrue(Arrays.stream(pixels(renderer.rasterize(both,both.projection(camera,frame),zero,0))).allMatch(p -> p==0));
        assertTrue(Arrays.stream(pixels(renderer.render(both,camera,frame,zero,0))).allMatch(p -> p==0));
        // Turning the camera around must show the game's actual reverse material.
        assertTrue(Arrays.stream(pixels(renderer.render(both,new CameraView(Math.PI,0,1),frame,zero,0))).anyMatch(p -> (p>>>24)==255));
    }

    static final class Fixture
    {
        ModelSnapshot mesh;
        int[] pixels;
        int textureId,direction,speed;
    }

    private void actualCape(String name) throws IOException
    {
        String directory=System.getProperty("modelpopout.capeFixtures");
        Assume.assumeTrue("Optional local game-cache fixtures require modelpopout.capeFixtures",directory!=null);
        Path path=Path.of(directory,name+".json");
        Assume.assumeTrue("Optional local game-cache fixture: "+path,Files.isRegularFile(path));
        String source=Files.readString(path);Fixture fixture=CapeFixtureReader.read(source);
        ModelSnapshot mesh=fixture.mesh.toRgb();ModelFrame frame=ModelFrame.fit(mesh);
        TextureSet textures=new TextureSet(Collections.singletonMap(fixture.textureId,
            new TextureSet.Pixels(fixture.pixels,fixture.direction,fixture.speed,0,0)),0,false);
        assertTrue(textures.animated());
        assertFalse(textures.texture(fixture.textureId).cutouts);
        boolean cached=false,changed=false;
        ModelRenderer renderer=new ModelRenderer();
        for(int angle=0;angle<8;angle++)
        {
            CameraView camera=new CameraView(angle*Math.PI/4,.15,1);
            ModelProjection projection=mesh.projection(camera,frame);
            ModelSnapshot reference=CapeFixtureReader.read(source).mesh.toRgb();
            // Independent native visibility oracle: (xA-xB)*(yC-yB)-(yA-yB)*(xC-xB)>0.
            for(int f=0;f<reference.a.length;f++)
            {
                int a=reference.a[f],b=reference.b[f],c=reference.c[f];
                double facing=(projection.x[a]-projection.x[b])*(projection.y[c]-projection.y[b])
                    -(projection.y[a]-projection.y[b])*(projection.x[c]-projection.x[b]);
                if(facing<=1e-8) reference.colorC[f]=-1;
            }
            TextureRasterPlan plan=projection.rasterPlan(mesh);
            cached |= plan!=null && plan.fragments()>0;
            int[] initial=null;
            for(double phase:new double[]{0,.25,.5,1,64})
            {
                int[] expected=pixels(renderer.rasterize(reference,reference.projection(camera,frame),textures,phase));
                int[] general=pixels(renderer.rasterize(mesh,projection,textures,phase));
                assertArrayEquals(name+" native visible surfaces",expected,general);
                assertArrayEquals(name+" cached/general parity",general,pixels(renderer.render(mesh,camera,frame,textures,phase)));
                if(initial==null) initial=general;
                else changed |= !Arrays.equals(initial,general);
            }
        }
        assertTrue("Actually exercised cached texture fragments",cached);
        assertTrue("Actual lava pixels animate with unchanged geometry",changed);
    }

    @Test public void actualFireCapeCacheAssetMatchesVisibleSurfaceOracle() throws IOException { actualCape("fire-cape"); }
    @Test public void actualInfernalCapeCacheAssetMatchesVisibleSurfaceOracle() throws IOException { actualCape("infernal-cape"); }
}

