package com.modelpopout;

import org.junit.Test;
import static org.junit.Assert.*;

public class LiveCaptureGateTest
{
    private LiveCaptureGate ready()
    {
        LiveCaptureGate gate = new LiveCaptureGate();
        gate.open();
        gate.setLoggedIn(true);
        return gate;
    }

    @Test public void averagesTwentySamplesPerSecondOnTwentyMillisecondTicks()
    {
        LiveCaptureGate gate = ready();
        int samples = 0;
        for (long ms = 0; ms < 1000; ms += 20)
        {
            long ticket = gate.acquire(ms * 1_000_000);
            if (ticket >= 0) { samples++; assertTrue(gate.complete(ticket)); }
        }
        assertEquals(20, samples);
    }

    @Test public void slowTicksSampleFreshStateWithoutCatchUpBursts()
    {
        LiveCaptureGate gate = ready();
        int samples = 0;
        for (long ms = 0; ms < 1000; ms += 200)
        {
            long ticket = gate.acquire(ms * 1_000_000);
            assertTrue(ticket >= 0);
            samples++;
            assertTrue(gate.complete(ticket));
            assertEquals(-1, gate.acquire(ms * 1_000_000));
        }
        assertEquals(5, samples);
    }

    @Test public void slowEdtAllowsOnlyOnePendingHandoff()
    {
        LiveCaptureGate gate = ready();
        long ticket = gate.acquire(0);
        for (long ms = 20; ms < 10000; ms += 20)
        {
            assertEquals(-1, gate.acquire(ms * 1_000_000));
        }
        assertTrue(gate.complete(ticket));
        assertTrue(gate.acquire(10_000_000_000L) >= 0);
    }

    @Test public void closeAndLogoutRejectOldCallbacksAndStopCapturing()
    {
        LiveCaptureGate gate = ready();
        long old = gate.acquire(0);
        gate.close();
        assertFalse(gate.complete(old));
        assertFalse(gate.current(old));
        assertEquals(-1, gate.acquire(100_000_000));
        gate.open();
        long fresh = gate.acquire(100_000_000);
        assertFalse(gate.complete(old));
        assertEquals(-1, gate.acquire(200_000_000));
        assertTrue(gate.complete(fresh));
        gate.setLoggedIn(false);
        assertEquals(-1, gate.acquire(300_000_000));
        assertFalse(gate.complete(fresh));
        gate.setLoggedIn(true);
        assertTrue(gate.acquire(300_000_000) >= 0);
    }

    @Test public void completionDoesNotBypassTheNextCaptureDeadline()
    {
        LiveCaptureGate gate = ready();
        long ticket = gate.acquire(0);
        assertTrue(gate.complete(ticket));
        assertEquals(-1,gate.acquire(1));
        assertEquals(-1,gate.acquire(49_999_999));
        long next = gate.acquire(50_000_000);
        assertTrue(next >= 0);
        assertEquals(-1,gate.acquire(100_000_000));
        assertTrue(gate.complete(next));
    }

    @Test public void configurationChangesRateImmediatelyAndClampsIt()
    {
        LiveCaptureGate gate = ready();
        gate.setRate(0);
        gate.complete(gate.acquire(0));
        assertEquals(-1, gate.acquire(999_999_999));
        gate.complete(gate.acquire(1_000_000_000));
        gate.setRate(1000);
        gate.complete(gate.acquire(1_000_000_001));
        assertEquals(-1, gate.acquire(1_020_000_000));
        assertTrue(gate.acquire(1_020_000_001) >= 0);
    }

    @Test public void negativeMonotonicClockValuesWork()
    {
        LiveCaptureGate gate = ready();
        gate.complete(gate.acquire(-1_000_000_000));
        assertEquals(-1, gate.acquire(-960_000_000));
        assertTrue(gate.acquire(-940_000_000) >= 0);
    }
}

package com.modelpopout;

import org.junit.Test;
import static org.junit.Assert.*;

public class LiveViewStateTest
{
    private ModelSnapshot pose(float y, int color, byte alpha)
    {
        return new ModelSnapshot(new float[]{0, 10, -10}, new float[]{y, 10, 10}, new float[]{0, 0, 0},
            new int[]{0}, new int[]{1}, new int[]{2}, new int[]{color}, new int[]{color}, new int[]{color}, new byte[]{alpha});
    }

    @Test public void identicalAppearanceSkipsRenderingButManualCaptureForcesIt()
    {
        LiveViewState state = new LiveViewState();
        assertTrue(state.updateModel(pose(0, 0xff0000, (byte) 0), false));
        LiveViewState.RenderRequest frame = state.begin();
        assertNotNull(frame);
        state.finish(frame);
        assertFalse(state.updateModel(pose(0, 0xff0000, (byte) 0), false));
        assertNull(state.begin());
        assertTrue(state.updateModel(pose(0, 0xff0000, (byte) 0), true));
        assertNotNull(state.begin());
    }

    @Test public void animationColorAndTransparencyChangesAreDetected()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        assertTrue(state.updateModel(pose(1, 0xff0000, (byte) 0), false));
        assertTrue(state.updateModel(pose(1, 0x00ff00, (byte) 0), false));
        assertTrue(state.updateModel(pose(1, 0x00ff00, (byte) 100), false));
    }

    @Test public void fallingBehindKeepsOnlyLatestPoseAndCamera()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        LiveViewState.RenderRequest first = state.begin();
        CameraView camera = new CameraView(1.5, .5, 2);
        ModelSnapshot last = null;
        for (int i = 1; i <= 1000; i++)
        {
            last = pose(i, 0xff0000, (byte) 0);
            state.updateModel(last, false);
            state.setCamera(camera);
            assertNull(state.begin());
        }
        assertTrue(state.finish(first));
        LiveViewState.RenderRequest latest = state.begin();
        assertSame(last, latest.model);
        assertSame(camera, latest.camera);
        state.finish(latest);
        assertNull(state.begin());
    }

    @Test public void modelUpdatesAndLogoutPreserveCamera()
    {
        LiveViewState state = new LiveViewState();
        CameraView camera = new CameraView(2, -.5, 1.8);
        state.setCamera(camera);
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        state.clear();
        assertNull(state.begin());
        state.updateModel(pose(1, 0x00ff00, (byte) 0), false);
        assertSame(camera, state.begin().camera);
    }

    @Test public void staleCompletionCannotReleaseNewSessionRender()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        LiveViewState.RenderRequest old = state.begin();
        state.clear();
        state.updateModel(pose(1, 0x00ff00, (byte) 0), false);
        assertNull(state.begin()); // Closing/reopening cannot add a second real rendering task.
        assertFalse(state.finish(old)); // Releases the slot, but rejects the invalidated image.
        LiveViewState.RenderRequest fresh = state.begin();
        assertNotNull(fresh);
        assertFalse(state.finish(old)); // Duplicate/stale completions cannot release the new task.
        assertNull(state.begin());
        assertTrue(state.finish(fresh));
    }

    @Test public void completedButNotYetPresentedSceneIsInvalidAfterNpcLayoutOrLogoutChanges()
    {
        LiveViewState state = new LiveViewState();state.setNpcEnabled(true);
        state.updateModel(pose(0,0xff0000,(byte)0),false);
        LiveViewState.RenderRequest completed = state.begin();assertTrue(state.finish(completed));
        assertTrue(state.valid(completed));
        state.setNpcEnabled(false);assertFalse(state.valid(completed));
        LiveViewState.RenderRequest replacement = state.begin();assertTrue(state.finish(replacement));
        assertTrue(state.valid(replacement));state.clear();assertFalse(state.valid(replacement));
    }

    @Test public void equivalentCameraDoesNotCreateDuplicateRenderWork()
    {
        LiveViewState state = new LiveViewState();state.updateModel(pose(0,0xff0000,(byte)0),false);
        state.finish(state.begin());
        state.setCamera(new CameraView(CameraView.DEFAULT.yaw,CameraView.DEFAULT.pitch,CameraView.DEFAULT.zoom));
        assertFalse(state.needsRender());
    }

    @Test public void snapshotConstructorOwnsInputArrays()
    {
        float[] x = {0, 10, -10}, y = {0, 10, 10}, z = {0, 0, 0};
        int[] a = {0}, b = {1}, c = {2}, colors = {0xff0000};
        byte[] alpha = {0};
        ModelSnapshot snapshot = new ModelSnapshot(x, y, z, a, b, c, colors, colors, colors, alpha);
        ModelSnapshot original = pose(0, 0xff0000, (byte) 0);
        x[0] = y[0] = z[0] = 99; a[0] = b[0] = c[0] = 99; colors[0] = 0; alpha[0] = 100;
        assertTrue(snapshot.sameAppearance(original));
    }
}

package com.modelpopout;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class MinimalWindowTest
{
    @Test public void transparentSurfaceHasNoDuplicateControlsOrFooter() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            assertEquals(0,buttons(surface).size());
            assertNoLabels(surface);
            java.awt.BorderLayout layout = (java.awt.BorderLayout) surface.getLayout();
            assertNull(layout.getLayoutComponent(java.awt.BorderLayout.NORTH));
            assertNull(layout.getLayoutComponent(java.awt.BorderLayout.SOUTH));
        });
    }

    @Test public void backgroundFadesWithUiWhileModelsStayOpaqueAndZeroOpacityHoverRecoversControls() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            surface.setSize(120,80);
            surface.doLayout();
            surface.modelPainter = g -> { g.setColor(java.awt.Color.RED); g.fillRect(60,60,1,1); };
            java.awt.image.BufferedImage image = new java.awt.image.BufferedImage(120,80,java.awt.image.BufferedImage.TYPE_INT_ARGB);
            java.awt.Graphics2D g = image.createGraphics();
            try
            {
                for (int opacity : new int[]{100,50,0})
                {
                    surface.opacity = opacity;
                    surface.paint(g);
                    assertEquals(BackgroundOpacity.alpha(opacity),image.getRGB(106,14) >>> 24); // UI background
                    assertEquals(0xffff0000,image.getRGB(60,60));
                }
                surface.reveal = true;
                surface.paint(g);
                assertEquals(255,image.getRGB(106,14) >>> 24);
                assertNull(((java.awt.BorderLayout) surface.getLayout()).getLayoutComponent(java.awt.BorderLayout.SOUTH));
            }
            finally { g.dispose(); }
        });
    }

    @Test public void edgesAndCornersResizeWithoutMovingTheOppositeAnchorOrBreakingMinimumSize()
    {
        Rectangle start = new Rectangle(100,200,600,400);
        Dimension min = new Dimension(480,300);
        for (int edges : new int[]{1,2,4,8,3,9,6,12})
        {
            assertNotEquals(java.awt.Cursor.DEFAULT_CURSOR,WindowGeometry.cursor(edges));
            Rectangle resized = WindowGeometry.resize(start,edges,50,40,min);
            if ((edges & WindowGeometry.WEST) != 0) assertEquals(start.x+start.width,resized.x+resized.width);
            else assertEquals(start.x,resized.x);
            if ((edges & WindowGeometry.NORTH) != 0) assertEquals(start.y+start.height,resized.y+resized.height);
            else assertEquals(start.y,resized.y);
            Rectangle clamped = WindowGeometry.resize(start,edges,
                (edges & WindowGeometry.WEST) != 0 ? 10000 : -10000,
                (edges & WindowGeometry.NORTH) != 0 ? 10000 : -10000,min);
            assertTrue(clamped.width >= min.width);
            assertTrue(clamped.height >= min.height);
        }
        assertEquals(WindowGeometry.NORTH | WindowGeometry.WEST,WindowGeometry.edges(0,0,600,400));
        assertEquals(WindowGeometry.SOUTH | WindowGeometry.EAST,WindowGeometry.edges(599,399,600,400));
        assertEquals(WindowGeometry.WEST,WindowGeometry.edges(2,200,600,400));
        assertEquals(WindowGeometry.EAST,WindowGeometry.edges(598,200,600,400));
        assertEquals(0,WindowGeometry.edges(300,200,600,400));
    }

    private static List<JButton> buttons(Container root)
    {
        List<JButton> result = new ArrayList<>();
        for (Component child : root.getComponents())
        {
            if (child instanceof JButton) result.add((JButton) child);
            else if (child instanceof Container) result.addAll(buttons((Container) child));
        }
        return result;
    }

    private static void assertNoLabels(Container root)
    {
        for (Component child : root.getComponents())
        {
            assertFalse(child instanceof JLabel);
            if (child instanceof Container) assertNoLabels((Container) child);
        }
    }
}

