            desktop.waitForIdle();
            SwingUtilities.invokeAndWait(() -> {
                WindowTitleBar bar=(WindowTitleBar)((BorderLayout)windows[0].getContentPane().getLayout()).getLayoutComponent(BorderLayout.NORTH);
                bar.maximize.doClick();
            });
            desktop.waitForIdle();
            SwingUtilities.invokeAndWait(() -> {
                ViewerWindow frame=windows[0];
