package com.modelpopout;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.*;
import org.junit.*;
import static org.junit.Assert.*;
import static com.modelpopout.InspectionFixtures.*;

/** Reproduces RuneLite's global decoration setting rather than testing only a plain JFrame environment. */
public class NativeWindowDecorationTest
{
    @Test public void inheritedRuneLiteAndMetalBarsAreUsedWithoutAnExtraCustomBar() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            LookAndFeel original=UIManager.getLookAndFeel();boolean decorated=JFrame.isDefaultLookAndFeelDecorated();
            try
            {
                for (LookAndFeel laf:new LookAndFeel[]{new javax.swing.plaf.metal.MetalLookAndFeel(),new net.runelite.client.ui.laf.RuneLiteLAF()})
                {
                    UIManager.setLookAndFeel(laf);JFrame.setDefaultLookAndFeelDecorated(true);
                    JFrame inherited=new JFrame("inherited decoration reproduction");
                    try
                    {
                        // This is the missing case in the original tests: undecorated does not mean no Swing bar.
                        assertTrue(inherited.isUndecorated());assertEquals(JRootPane.FRAME,inherited.getRootPane().getWindowDecorationStyle());
                        inherited.add(new WindowTitleBar(new WindowTitleBarTest.Actions()),BorderLayout.NORTH);
                        assertEquals("Legacy duplication occurs inside one frame",2,titlePanes(inherited));
                    }
                    finally { inherited.dispose(); }
                    ViewerWindow frame=ViewerWindow.create();
                    try
                    {
                        frame.setSize(480,360);frame.setVisible(true);
                        assertEquals(JRootPane.FRAME,frame.getRootPane().getWindowDecorationStyle());assertFalse(frame.hasBuiltInControls());
                        assertEquals(1,titlePanes(frame));
                        assertTrue("Inherited bar must provide minimize/maximize/close buttons",titleButtons(frame)>=3);
                        assertTrue(JFrame.isDefaultLookAndFeelDecorated());
                        frame.applyWindowControls();frame.validate();
                        assertFalse(frame.hasBuiltInControls());
                        assertEquals(JRootPane.FRAME,frame.getRootPane().getWindowDecorationStyle());
                        assertEquals(1,titlePanes(frame));
                        assertTrue(frame.isDisplayable());assertTrue(frame.isUndecorated());
                        assertFalse(frame.getRootPane().isOpaque());assertFalse(frame.getLayeredPane().isOpaque());assertFalse(frame.getContentPane().isOpaque());
                        verifyRoutingAndAlpha(frame);
                    }
                    finally { frame.dispose(); }
                }
            }
            catch (UnsupportedLookAndFeelException failure) { throw new AssertionError(failure); }
            finally
            {
                JFrame.setDefaultLookAndFeelDecorated(decorated);
                try { UIManager.setLookAndFeel(original); }
                catch (UnsupportedLookAndFeelException failure) { throw new AssertionError(failure); }
            }
        });
    }

    @Test public void absentInheritedDecorationsAlwaysGetBuiltInControls() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            boolean decorated=JFrame.isDefaultLookAndFeelDecorated();
            JFrame.setDefaultLookAndFeelDecorated(false);
            ViewerWindow frame=ViewerWindow.create();
            try
            {
                frame.setSize(480,360);frame.setVisible(true);
                frame.applyWindowControls();frame.validate();
                assertTrue(frame.hasBuiltInControls());assertEquals(JRootPane.NONE,frame.getRootPane().getWindowDecorationStyle());
                assertEquals(1,titlePanes(frame));verifyRoutingAndAlpha(frame);
            }
            finally { frame.dispose();JFrame.setDefaultLookAndFeelDecorated(decorated); }
        });
    }

    private static void verifyRoutingAndAlpha(ViewerWindow frame)
    {
        AtomicInteger paints=new AtomicInteger();
        JComponent probe=new JComponent()
        { @Override protected void paintComponent(Graphics g) { paints.incrementAndGet();assertTrue(frame.isPaintingWindow()); } };
        probe.setOpaque(true);probe.setBounds(2,2,10,10);frame.getLayeredPane().add(probe,JLayeredPane.POPUP_LAYER);
        try
        {
            probe.paintImmediately(0,0,10,10);
            assertEquals("Opaque siblings must ascend to the native presentation boundary",0,paints.get());
            for (int opacity:new int[]{0,30,50,100})
            {
                frame.applyBackgroundOpacity(opacity);frame.validate();
                BufferedImage image=new BufferedImage(frame.getWidth(),frame.getHeight(),BufferedImage.TYPE_INT_ARGB);
                Graphics2D g=image.createGraphics();try { frame.paint(g); } finally { g.dispose(); }
                Point viewport=SwingUtilities.convertPoint(frame.getContentPane(),80,80,frame);
                assertEquals(BackgroundOpacity.alpha(frame.effectiveOpacity()),image.getRGB(viewport.x,viewport.y)>>>24);
                Container title=titlePane(frame);
                if (title!=null)
                {
                    Point chrome=SwingUtilities.convertPoint(title,title.getWidth()/2,title.getHeight()/2,frame);
                    assertEquals("Title bar must remain opaque at every viewport opacity",255,image.getRGB(chrome.x,chrome.y)>>>24);
                }
            }
            assertEquals(4,paints.get());
        }
        finally { frame.getLayeredPane().remove(probe); }
    }

    @Test public void automaticAppliesToIndependentInspectionWindowsAndSurvivesSettingsChanges() throws Exception
    {
        requireDesktop();
        ModelPopoutConfig config=new ModelPopoutConfig() {};
        SwingUtilities.invokeAndWait(() -> {
            InspectionRenderScheduler scheduler=new InspectionRenderScheduler(new Worker(),SwingUtilities::invokeLater);
            InspectionSession[] sessions=new InspectionSession[2];ViewerWindow[] frames=new ViewerWindow[2];
            try
            {
                for (int i=0;i<2;i++)
                {
                    sessions[i]=new InspectionSession(config,scheduler,() -> {},v -> {});sessions[i].open("decoration test "+i);
                    for (Window window:Window.getWindows()) if (window instanceof ViewerWindow
                        && ((ViewerWindow)window).getTitle().equals("Popout — decoration test "+i)) frames[i]=(ViewerWindow)window;
                    assertNotNull(frames[i]);assertEquals(1,titlePanes(frames[i]));
                }
                for (int i=0;i<2;i++)
                {
                    boolean builtIn=frames[i].hasBuiltInControls();
                    sessions[i].settingsChanged();
                    assertEquals(builtIn,frames[i].hasBuiltInControls());assertEquals(1,titlePanes(frames[i]));
                    assertFalse(sessions[i].closed());assertTrue(frames[i].isDisplayable());
                }
                frames[0].dispatchEvent(new java.awt.event.WindowEvent(frames[0],java.awt.event.WindowEvent.WINDOW_CLOSING));
                assertTrue(frames[1].isDisplayable());
            }
            finally { for (InspectionSession session:sessions) if (session!=null) session.close(); }
        });
    }

    static Container titlePane(Container container)
    {
        if (container instanceof WindowTitleBar || container.getClass().getSimpleName().endsWith("TitlePane")) return container;
        for (Component child:container.getComponents()) if (child instanceof Container)
        {
            Container title=titlePane((Container)child);
            if (title!=null) return title;
        }
        return null;
    }

    static int titleButtons(Container container)
    {
        int buttons=0;
        for (Component child:container.getComponents())
        {
            if (child instanceof Container && child.getClass().getSimpleName().endsWith("TitlePane"))
                buttons+=buttons((Container)child);
            else if (child instanceof Container) buttons+=titleButtons((Container)child);
        }
        return buttons;
    }

    private static int buttons(Container container)
    {
        int count=0;
        for (Component child:container.getComponents())
        {
            if (child instanceof JButton) count++;
            else if (child instanceof Container) count+=buttons((Container)child);
        }
        return count;
    }

    static int titlePanes(Container container)
    {
        int count=container instanceof WindowTitleBar || container.getClass().getSimpleName().endsWith("TitlePane") ? 1 : 0;
        for (Component child:container.getComponents()) if (child instanceof Container) count+=titlePanes((Container)child);
        return count;
    }

    static void requireDesktop()
    {
        Assume.assumeTrue(Boolean.getBoolean("modelpopout.desktopTests"));Assume.assumeFalse(GraphicsEnvironment.isHeadless());
    }
}

package com.modelpopout;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GraphicsEnvironment;
import java.awt.image.BufferedImage;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import org.junit.Assume;
import org.junit.Test;
import static org.junit.Assert.*;

/** Opt-in integration checks: use desktopPresentationTest on the actual desktop/JDK. */
public class NativeWindowPresentationTest
{
    @Test public void inheritedAwtPaintExposesItsClearBeforeChildPainting() throws Exception
    {
        requireDesktop();
        boolean[] supported = {false};
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow capability = ViewerWindow.create();
            capability.applyBackgroundOpacity(0);
            supported[0] = capability.effectiveOpacity() == 0;
            capability.dispose();
        });
        Assume.assumeTrue("Desktop does not support per-pixel translucent windows",supported[0]);
        SwingUtilities.invokeAndWait(() -> {
            BufferedImage screen = new BufferedImage(120,120,BufferedImage.TYPE_INT_ARGB);
            screen.setRGB(60,60,Color.RED.getRGB());
            JFrame legacy = new JFrame();
            legacy.setUndecorated(true);
            legacy.setBackground(new Color(0,0,0,0));
            int[] during = {Color.RED.getRGB()};
            legacy.setContentPane(new JPanel()
            {
                @Override protected void paintComponent(Graphics g)
                {
                    during[0] = screen.getRGB(60,60);
                    g.setColor(Color.GREEN);
                    g.fillRect(60,60,1,1);
                }
            });
            legacy.getRootPane().setDoubleBuffered(false);
            legacy.getContentPane().setBackground(new Color(0,0,0,0));
            legacy.setSize(120,120);
            Graphics2D target = screen.createGraphics();
            try
            {
                legacy.setVisible(true);
                legacy.paint(target);
                assertEquals("Real Window.paint clears the destination before its child paints",0,during[0]);
            }
            finally { target.dispose(); legacy.dispose(); }
        });
    }

    @Test public void viewerTopLevelPaintRetainsPreviousFrameDuringRealAwtClear() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow viewer = ViewerWindow.create();
            BufferedImage screen = new BufferedImage(120,120,BufferedImage.TYPE_INT_ARGB);
            viewer.setSize(120,120);
            Graphics2D target = screen.createGraphics();
            try
            {
                viewer.setVisible(true);
                for (int opacity : new int[]{100,50,0})
                {
                    viewer.applyBackgroundOpacity(opacity);
                    for (int i = 0; i < 50; i++)
                    {
                        screen.setRGB(60,60,Color.RED.getRGB());
                        boolean[] called = {false};
                        viewer.setModelPainter(g -> {
                            called[0] = true;
                            assertTrue("Presentation diagnostic must identify the protected top-level path",viewer.isPaintingWindow());
                            assertEquals("Native destination cleared before completed hierarchy",
                                Color.RED.getRGB(),screen.getRGB(60,60));
                            g.setColor(Color.GREEN);
                            g.fillRect(60,60,1,1);
                        });
                        viewer.paint(target);
                        assertFalse(viewer.isPaintingWindow());
                        assertTrue(called[0]);
                        assertEquals(Color.GREEN.getRGB(),screen.getRGB(60,60));
                    }
                }
            }
            finally { viewer.setModelPainter(g -> {}); target.dispose(); viewer.dispose(); }
        });
    }

    @Test public void savedStackingPreferenceCanChangeAndSurviveWindowRecreation() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            for(int opening=0;opening<2;opening++)
            {
                ViewerWindow viewer=ViewerWindow.create();
                try
                {
                    assertFalse(viewer.isAlwaysOnTop());
                    boolean supported=viewer.isAlwaysOnTopSupported();
                    if(viewer.applyAlwaysOnTop(true))
                    {
                        assertTrue(supported);
                        assertTrue(viewer.isAlwaysOnTop());
                    }
                    viewer.applyAlwaysOnTop(false);
                    assertFalse(viewer.isAlwaysOnTop());
                }
                finally { viewer.dispose(); }
            }
        });
    }

    @Test public void realWindowBackgroundTransitionsKeepAllSwingRepaintsAboveTheBuffer() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow viewer=ViewerWindow.create();
            try
            {
                viewer.setSize(120,120);viewer.setVisible(true);
                viewer.applyBackgroundOpacity(0);
                boolean transparent=!viewer.isOpaque();
                // Public Window API triggers the actual JDK setLayersOpaque(true) path.
                viewer.setBackground(Color.BLACK);
                assertTrue(viewer.isOpaque());
                assertFalse(viewer.getRootPane().isOpaque());
                assertFalse(viewer.getLayeredPane().isOpaque());
                assertFalse(viewer.getContentPane().isOpaque());
                final int[] draws={0};viewer.setModelPainter(g -> {
                    draws[0]++;assertTrue("Swing painting bypassed WindowPresentation",viewer.isPaintingWindow());
                });
                javax.swing.JComponent surface=(javax.swing.JComponent)viewer.getContentPane();
                surface.paintImmediately(0,0,120,120);
                assertEquals("Request is queued at Window, not directly painted by Swing",0,draws[0]);
                viewer.applyBackgroundOpacity(50);
                if(transparent) assertFalse(viewer.isOpaque());
                assertFalse(viewer.getRootPane().isOpaque());assertFalse(surface.isOpaque());
            }
            finally {viewer.setModelPainter(g -> {});viewer.dispose();}
        });
    }

    @Test public void nativeOpacityTransitionsRetainCapableConfigurationAndFinalArgb() throws Exception
    {
        requireDesktop();
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow viewer=ViewerWindow.create();
            BufferedImage target=new BufferedImage(120,120,BufferedImage.TYPE_INT_ARGB);
            Graphics2D g=target.createGraphics();
            try
            {
                viewer.setSize(120,120);viewer.setVisible(true);viewer.applyBackgroundOpacity(0);
                Assume.assumeTrue("Desktop has no usable per-pixel translucency",viewer.effectiveOpacity()==0);
                viewer.setModelPainter(layer -> {assertTrue(viewer.isPaintingWindow());layer.setColor(Color.RED);layer.fillRect(60,60,1,1);});
                for(int opacity:new int[]{0,30,50,100,30,0})
                {
                    viewer.applyBackgroundOpacity(opacity);viewer.getRootPane().doLayout();viewer.getContentPane().doLayout();
                    assertEquals(0,viewer.getBackground().getAlpha());assertFalse(viewer.isOpaque());
                    assertTrue(viewer.getGraphicsConfiguration().isTranslucencyCapable());
                    assertFalse(viewer.getRootPane().isOpaque());assertFalse(viewer.getLayeredPane().isOpaque());assertFalse(viewer.getContentPane().isOpaque());
                    viewer.paint(g);
                    assertEquals(BackgroundOpacity.alpha(opacity),target.getRGB(80,80)>>>24);
                    assertEquals(0xffff0000,target.getRGB(60,60));
                }
            }
            finally {viewer.setModelPainter(layer -> {});g.dispose();viewer.dispose();}
        });
    }

    private static void requireDesktop()
    {
        Assume.assumeTrue("Enable with desktopPresentationTest",Boolean.getBoolean("modelpopout.desktopTests"));
        Assume.assumeFalse(GraphicsEnvironment.isHeadless());
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class NpcSceneTest
{
    private ModelSnapshot pose(float height,int color)
    {
        return new ModelSnapshot(new float[]{-40,40,0},new float[]{-height,-height,0},new float[3],
            new int[]{0},new int[]{2},new int[]{1},new int[]{color},new int[]{color},new int[]{color},new byte[1]);
    }

    private LiveViewState state()
    {
        LiveViewState state = new LiveViewState();
        state.setCamera(new CameraView(0,0,1));
        state.setNpcEnabled(true);
        state.updateModel(pose(100,0xff0000),false);
        return state;
    }

    @Test public void npcAnimationsAndTransformationsKeepBothReferencesAndCameraStable()
    {
        LiveViewState state = state();
        state.updateNpc(pose(120,0x00ff00),7);
        LiveViewState.RenderRequest first = state.begin();
        ModelRenderer renderer = new ModelRenderer();
        BufferedImage initial = renderer.renderScene(first);
        BufferedImage playerRaster = renderer.render(first.model,first.camera,first.framing);
        assertEquals(1024,initial.getWidth());
        int[] left = initial.getRGB(0,0,512,512,null,0,512);
        state.finish(first);
        state.updateNpc(pose(220,0x0000ff),7); // Same NPC object changes its native form and pose.
        LiveViewState.RenderRequest transformed = state.begin();
        assertSame(first.framing,transformed.framing);
        assertSame(first.npcFraming,transformed.npcFraming);
        assertSame(first.camera,transformed.camera);
        BufferedImage changed = renderer.renderScene(transformed);
        assertSame("NPC changes reuse the unchanged player's raster",playerRaster,
            renderer.render(transformed.model,transformed.camera,transformed.framing));
        assertArrayEquals(left,changed.getRGB(0,0,512,512,null,0,512));
        assertFalse(Arrays.equals(initial.getRGB(512,0,512,512,null,0,512),changed.getRGB(512,0,512,512,null,0,512)));
        state.finish(transformed);
        assertFalse(state.updateNpc(pose(220,0x0000ff),7));
        assertNull(state.begin());
    }

    @Test public void switchInvalidatesOldImageAndInitializesOnlyNewNpcFraming()
    {
        LiveViewState state = state();
        state.updateNpc(pose(100,0x00ff00),1);
        LiveViewState.RenderRequest old = state.begin();
        state.updateNpc(pose(300,0x0000ff),2);
        assertNull(state.begin());
        assertFalse(state.finish(old));
        LiveViewState.RenderRequest next = state.begin();
        assertSame(old.framing,next.framing);
        assertNotSame(old.npcFraming,next.npcFraming);
        assertEquals(2,next.npcKey);
        assertFalse(state.removeNpc(1)); // Late removal from an old target cannot remove the new one.
    }

    @Test public void despawnClearsOnlyNpcAndKeepsPairViewportWithoutRefittingPlayer()
    {
        LiveViewState state = state();
        state.updateNpc(pose(120,0x00ff00),7);
        LiveViewState.RenderRequest old = state.begin();
        state.finish(old);
        assertTrue(state.removeNpc(7));
        assertFalse(state.hasNpc());
        LiveViewState.RenderRequest removed = state.begin();
        assertSame(old.framing,removed.framing);
        BufferedImage image = new ModelRenderer().renderScene(removed);
        assertEquals(1024,image.getWidth());
        assertEquals(0,image.getRGB(768,256) >>> 24);
    }

    @Test public void temporaryNpcModelUnavailabilityDoesNotReframeItsNextPose()
    {
        LiveViewState state = state();
        state.updateNpc(pose(120,0x00ff00),7);
        LiveViewState.RenderRequest first = state.begin();
        state.finish(first);
        state.updateNpc(null,7);
        assertFalse(state.hasNpc());
        LiveViewState.RenderRequest unavailable = state.begin();
        state.finish(unavailable);
        state.updateNpc(pose(220,0x00ff00),7);
        assertSame(first.npcFraming,state.begin().npcFraming);
    }

    @Test public void disabledNpcCannotBeRestoredByAnInFlightCapture()
    {
        LiveViewState state = state();
        state.updateNpc(pose(120,0x00ff00),7);
        LiveViewState.RenderRequest old = state.begin();
        state.setNpcEnabled(false);
        state.updateNpc(pose(120,0x00ff00),7);
        assertFalse(state.hasNpc());
        assertFalse(state.finish(old));
        BufferedImage image = new ModelRenderer().renderScene(state.begin());
        assertEquals(512,image.getWidth());
    }

    @Test public void closeOrStopClearsNpcAndInvalidatesBusySceneWithoutQueueingMoreWork()
    {
        LiveViewState state = state();
        state.updateNpc(pose(120,0x00ff00),7);
        LiveViewState.RenderRequest busy = state.begin();
        state.clear();
        assertFalse(state.hasNpc());
        assertNull(state.begin());
        assertFalse(state.finish(busy));
        assertNull(state.begin());
    }
}

package com.modelpopout;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class NpcSelectorTest
{
    private NpcSelector.Candidate<Object> npc(Object identity, int index, boolean present, boolean attacking, boolean dead)
    {
        return new NpcSelector.Candidate<>(identity,index,present,attacking,dead,true);
    }

    @Test public void directTargetWinsOverSeveralAttackersAndOldTarget()
    {
        Object direct = new Object(), old = new Object(), third = new Object();
        assertSame(direct,NpcSelector.select(direct,old,Arrays.asList(
            npc(old,1,true,true,false),npc(third,2,true,true,false),npc(direct,10,true,false,false))));
    }

    @Test public void keepsAttackerToAvoidFlickeringBetweenSeveralNpcs()
    {
        Object a = new Object(), b = new Object();
        assertSame(b,NpcSelector.select(null,b,Arrays.asList(npc(a,1,true,true,false),npc(b,2,true,true,false))));
        assertSame(a,NpcSelector.select(null,null,Arrays.asList(npc(b,2,true,true,false),npc(a,1,true,true,false))));
    }

    @Test public void combatEndingOrDespawnRemovesLivingNpc()
    {
        Object npc = new Object();
        assertNull(NpcSelector.select(null,npc,Arrays.asList(npc(npc,1,true,false,false))));
        assertNull(NpcSelector.select(npc,npc,Arrays.asList(npc(npc,1,false,true,false))));
    }

    @Test public void selectedDeathAnimationRemainsOnlyWhilePresentUnlessNewTargetWins()
    {
