public class TextureRenderingTest
{
    static class TexturedModel extends TestModel
    {
        final float[] x={-80,80,-80}, y={-80,-80,80}, z={0,0,0};
        final short[] textures={0};
        final byte[] alpha={0}, mapping={-1};
        // Match native screen-space winding; the UV basis follows face vertex order.
        final int[] ia={0},ib={2},ic={1};
        @Override public int getVerticesCount(){return 3;}
        @Override public float[] getVerticesX(){return x;}
        @Override public float[] getVerticesY(){return y;}
        @Override public float[] getVerticesZ(){return z;}
        @Override public int getFaceCount(){return 1;}
        @Override public int[] getFaceIndices1(){return ia;}
        @Override public int[] getFaceIndices2(){return ib;}
        @Override public int[] getFaceIndices3(){return ic;}
        @Override public int[] getFaceColors1(){return new int[]{127};}
        @Override public int[] getFaceColors2(){return new int[]{127};}
        @Override public int[] getFaceColors3(){return new int[]{127};}
        @Override public byte[] getFaceTransparencies(){return alpha;}
        @Override public short[] getFaceTextures(){return textures;}
        @Override public byte[] getTextureFaces(){return mapping;}
        @Override public int[] getTexIndices1(){return new int[]{0};}
        @Override public int[] getTexIndices2(){return new int[]{2};}
        @Override public int[] getTexIndices3(){return new int[]{1};}
    }
    static TextureSet texture(int[] pixels)
    {
        return new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(pixels,0,0,0,0)),0,false);
    }
    static TextureProvider provider(Texture[] metadata,int[] pixels)
    {
        return new TextureProvider()
        {
            @Override public double getBrightness(){return .8;}
            @Override public void setBrightness(double value){throw new AssertionError("Must never change native brightness");}
            @Override public Texture[] getTextures(){return metadata;}
            @Override public int[] load(int id){assertEquals(0,id);return pixels;}
            @Override public int getDefaultColor(int id){return 20000;}
        };
    }
    @Test public void referencedTextureCaptureCopiesOnlyOnceAndNeverMutatesProviderPixels()
    {
        int[] source = {0xff0000,0x00ff00,0x0000ff,0xffffff};
        TestTexture metadata = new TestTexture(source,1,2);
        TextureProvider provider = provider(new Texture[]{metadata},source);
        ModelSnapshot mesh = ModelSnapshot.capture(new TexturedModel(),provider);
        TextureSet copied = TextureSet.capture(provider,mesh,mesh,100,true);
        assertEquals(1,copied.textures.size());
        assertEquals(0xff0000,copied.textures.get(0).rgb[0]);
        source[0] = 0;
        assertEquals(0xff0000,copied.textures.get(0).rgb[0]);
        assertEquals(1,copied.textures.get(0).direction);
        assertEquals(2,copied.textures.get(0).speed);
        assertTrue(copied.gpu);
    }

    @Test public void temporaryTextureCacheMissRetainsOwnedPixelsAndDeduplicatesFailedLoads()
    {
        int[] pixels = {0xff0000,0x00ff00,0x0000ff,0xffffff};
        TestTexture metadata = new TestTexture(pixels,1,1);
        TextureProvider loaded = provider(new Texture[]{metadata},pixels);
        ModelSnapshot mesh = ModelSnapshot.capture(new TexturedModel(),loaded);
        TextureSet old = TextureSet.capture(loaded,mesh,mesh,10,true);
        int[] attempts = {0};
        TextureProvider missing = new TextureProvider()
        {
            @Override public double getBrightness(){return .8;}
            @Override public void setBrightness(double b){fail();}
            @Override public Texture[] getTextures(){return new Texture[]{metadata};}
            @Override public int[] load(int id){attempts[0]++;throw new IllegalStateException("temporarily unavailable");}
            @Override public int getDefaultColor(int id){return 0;}
        };
        TextureSet retained = TextureSet.capture(missing,mesh,mesh,11,true,old);
        assertEquals(1,attempts[0]);
        assertSame(old.texture(0),retained.texture(0));
        assertEquals(0xff0000,retained.texture(0).rgb[0]);
        TextureSet cpuOld=TextureSet.capture(loaded,mesh,mesh,10,false);
        TextureSet cpuRetained=TextureSet.capture(missing,mesh,mesh,11,false,cpuOld);
        assertSame(cpuOld.texture(0),cpuRetained.texture(0));
        assertEquals(0xff0000ff,cpuRetained.texture(0).sampleArgb(.25,.25,11,cpuRetained)); // Keeps the old bitmap's own phase origin.

    }

    @Test public void explicitAndImplicitMappingAgreeAndOwnedArraysSurviveNativeMutation()
    {
        TexturedModel nativeModel=new TexturedModel();
        ModelSnapshot implicit=ModelSnapshot.capture(nativeModel,null);
        assertArrayEquals(new double[]{0,0,1,0,0,1},implicit.uvs(),1e-9);
        nativeModel.mapping[0]=0;
        ModelSnapshot explicit=ModelSnapshot.capture(nativeModel,null);
        assertArrayEquals(implicit.uvs(),explicit.uvs(),1e-9);
        nativeModel.mapping[0]=127;nativeModel.x[0]=999;nativeModel.textures[0]=5;
        assertEquals(0,explicit.textureIds[0]);
        assertEquals(-80,explicit.x[0],0);
        assertEquals(0,explicit.textureFaces[0]);
    }
    @Test public void realTexturePixelsReplaceFallbackColorsAndZeroPixelsCutOut()
    {
        ModelSnapshot model=ModelSnapshot.capture(new TexturedModel(),null);
        ModelRenderer renderer=new ModelRenderer();CameraView camera=new CameraView(0,0,1);ModelFrame frame=ModelFrame.fit(model);
        BufferedImage filled=renderer.render(model,camera,frame,texture(new int[]{0xff0000,0x00ff00,0x0000ff,0xffffff}),0);
        assertEquals(0xffff0000,filled.getRGB(140,140));
        assertEquals(0xff0000ff,filled.getRGB(350,100));
        assertEquals(0xff00ff00,filled.getRGB(100,350));
        BufferedImage cutout=renderer.render(model,camera,frame,texture(new int[]{0}),0);
        assertEquals(0,cutout.getRGB(140,140));
        assertEquals(0xffff0000,filled.getRGB(140,140)); // New textures never mutate a published frame.
        assertSame(model.toRgb().projection(camera,frame),model.toRgb().projection(camera,frame));
    }
    @Test public void textureSamplingWrapsAndDoesNotTreatBlackModelDetailsAsCutouts()
    {
        TextureSet.Pixels pixels=new TextureSet.Pixels(new int[]{1,2,3,4},0,0,0,0);
        assertEquals(1,pixels.sample(0,0));
        assertEquals(1,pixels.sample(1,1));
        assertEquals(4,pixels.sample(-.1,-.1));
        assertEquals(2,pixels.sample(.75,.1));
    }
    @Test public void textureIdsAndLightingParticipateInAppearanceComparison()
    {
        TexturedModel nativeModel=new TexturedModel();ModelSnapshot first=ModelSnapshot.capture(nativeModel,null);
        nativeModel.textures[0]=1;
        assertFalse(first.sameAppearance(ModelSnapshot.capture(nativeModel,null)));
        nativeModel.textures[0]=0;nativeModel.mapping[0]=0;
        assertFalse(first.sameAppearance(ModelSnapshot.capture(nativeModel,null)));
    }
    @Test public void priorityTenInterleavesByDepthAndTintDoesNotOverrideTexturedLighting()
    {
        TexturedModel nativeModel = new TexturedModel()
        {
            @Override public int getVerticesCount(){return 9;}
            @Override public float[] getVerticesX(){return new float[9];}
            @Override public float[] getVerticesY(){return new float[9];}
            @Override public float[] getVerticesZ(){return new float[9];}
            @Override public int getFaceCount(){return 3;}
            @Override public int[] getFaceIndices1(){return new int[]{0,3,6};}
            @Override public int[] getFaceIndices2(){return new int[]{1,4,7};}
            @Override public int[] getFaceIndices3(){return new int[]{2,5,8};}
            @Override public int[] getFaceColors1(){return new int[]{127,127,127};}
            @Override public int[] getFaceColors2(){return getFaceColors1();}
            @Override public int[] getFaceColors3(){return getFaceColors1();}
            @Override public short[] getFaceTextures(){return new short[]{0,0,0};}
            @Override public byte[] getFaceTransparencies(){return new byte[3];}
            @Override public byte[] getTextureFaces(){return new byte[]{-1,-1,-1};}
            @Override public byte[] getFaceRenderPriorities(){return new byte[]{10,1,9};}
            @Override public byte getOverrideAmount(){return 64;}
            @Override public byte getOverrideHue(){return 20;}
        };
        ModelSnapshot snapshot = ModelSnapshot.capture(nativeModel,null);
        assertEquals(127,snapshot.colorA[0]); // Textured intensity is not an HSL tint target, even without a provider.
        assertArrayEquals(new int[]{0,1,2},FaceOrdering.order(snapshot,new double[]{10,10,10,0,0,0,-10,-10,-10}));
        assertArrayEquals(new int[]{1,2,0},FaceOrdering.order(snapshot,new double[]{-20,-20,-20,0,0,0,-10,-10,-10}));
    }

    @Test public void brightnessAndModelTransparencyUsePublicMetadata()
    {
        TexturedModel model=new TexturedModel()
        {
            @Override public byte getTransparency(){return (byte)128;}
            @Override public byte[] getFaceRenderPriorities(){return new byte[]{10};}
        };
        model.textures[0]=-1;
        ModelSnapshot snapshot=ModelSnapshot.capture(model,provider(null,null));
        assertEquals(126,snapshot.alpha[0]&255);
        assertEquals(10,snapshot.priorities[0]);
        assertNotEquals(ModelSnapshot.hslToRgb(10000,.6),ModelSnapshot.hslToRgb(10000,.9));
    }
    @Test public void degenerateMappingUsesDefaultColorInsteadOfInventingUvs()
    {
        TexturedModel model=new TexturedModel(){@Override public int[] getTexIndices3(){return new int[]{2};}};
        model.mapping[0]=0;
        ModelSnapshot snapshot=ModelSnapshot.capture(model,null);
        assertTrue(Double.isNaN(snapshot.uvs()[0]));
        BufferedImage image=new ModelRenderer().render(snapshot,new CameraView(0,0,1),ModelFrame.fit(snapshot),texture(new int[]{0xff0000}),0);
        assertNotEquals(0xffff0000,image.getRGB(140,140));
    }
}

package com.modelpopout;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class WindowCompositingTest
{
    @Test public void controlsAndModelsHaveIndependentAlphaAndReplacementClearsOldPixels() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            JLabel title = new JLabel("Title");
            title.setOpaque(true);
            title.setBackground(Color.BLUE);
            surface.add(title,BorderLayout.NORTH);
            surface.setSize(40,40);
            surface.doLayout();
            BufferedImage[] frame = {new BufferedImage(40,40,BufferedImage.TYPE_INT_ARGB)};
            frame[0].setRGB(20,30,0xffff0000);
            frame[0].setRGB(21,30,0xff00ff00); // second actor
            surface.modelPainter = g -> g.drawImage(frame[0],0,0,null);
            BufferedImage target = new BufferedImage(40,40,BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = target.createGraphics();
            try
            {
                assertTrue(surface.isPaintingOrigin());
                for (int opacity : new int[]{100,50,0})
                {
                    surface.opacity = opacity;
                    for (int i = 0; i < 50; i++)
                    {
                        surface.paint(g);
                        assertEquals(BackgroundOpacity.alpha(opacity),target.getRGB(39,1) >>> 24);
                        assertEquals(0xffff0000,target.getRGB(20,30));
                        assertEquals(0xff00ff00,target.getRGB(21,30));
                    }
                }
                surface.reveal = true;
                surface.paint(g);
                assertEquals(255,target.getRGB(39,1) >>> 24);
                surface.reveal = false;
                // A privately constructed replacement cannot change the published frame.
                BufferedImage replacement = new BufferedImage(40,40,BufferedImage.TYPE_INT_ARGB);
                replacement.setRGB(25,30,0xff000000);
                surface.paint(g);
                assertEquals(0xffff0000,target.getRGB(20,30));
                frame[0] = replacement;
                surface.paint(g);
                assertEquals(0,target.getRGB(20,30));
                assertEquals(0xff000000,target.getRGB(25,30));
                assertEquals(1,surface.getComponentCount());
            }
            finally { g.dispose(); }
        });
    }

    @Test public void wholeWindowArgbTransitionsPreserveUiAlphaAndOpaqueModels() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface=new ViewerWindow.Surface();surface.setSize(40,40);
            JLabel control=new JLabel("UI");control.setOpaque(true);control.setBackground(Color.BLUE);
            surface.add(control,BorderLayout.NORTH);surface.doLayout();
            surface.modelPainter=g -> {g.setColor(Color.RED);g.fillRect(10,30,1,1);g.setColor(Color.BLACK);g.fillRect(20,30,1,1);};
            WindowPresentation presentation=new WindowPresentation();
            BufferedImage target=new BufferedImage(40,40,BufferedImage.TYPE_INT_ARGB);Graphics2D g=target.createGraphics();
            try
            {
                for(int opacity:new int[]{100,30,0,50,100,0,30})
                {
                    surface.opacity=opacity;
                    for(int frame=0;frame<20;frame++)
                    {
                        presentation.paint(g,40,40,surface::paint);
                        assertEquals("Background alpha must survive the final presentation blit",BackgroundOpacity.alpha(opacity),target.getRGB(39,25)>>>24);
                        assertEquals("Controls use the UI alpha",BackgroundOpacity.alpha(opacity),target.getRGB(39,1)>>>24);
                        assertEquals(0xffff0000,target.getRGB(10,30));assertEquals(0xff000000,target.getRGB(20,30));
                        assertFalse(surface.isOpaque());
                    }
                }
            }
            finally {g.dispose();}
        });
    }

    @Test public void resizingReallocatesLayersAndPreservesPublishedModel() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            surface.opacity = 0;
            surface.modelPainter = g -> { g.setColor(Color.RED); g.fillRect(surface.getWidth()-1,surface.getHeight()-1,1,1); };
            for (int size : new int[]{20,80,10,40})
            {
                surface.setSize(size,size);
                surface.doLayout();
                BufferedImage target = new BufferedImage(size,size,BufferedImage.TYPE_INT_ARGB);
                Graphics2D g = target.createGraphics();
                try { surface.paint(g); }
                finally { g.dispose(); }
                assertEquals(0,target.getRGB(0,0));
                assertEquals(0xffff0000,target.getRGB(size-1,size-1));
            }
        });
    }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JRootPane;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class WindowPresentationTest
{
    @Test public void surfaceAndButtonDirtyRegionsReachTheNativeWindow() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            // A native-parent stand-in observes the real JComponent.paintImmediately routing.
            NativeParent parent = new NativeParent();
            parent.setSize(100,100);
            JRootPane root = new JRootPane();
            root.setOpaque(false);
            root.getLayeredPane().setOpaque(false);
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            JButton button = new JButton("Move");
            surface.add(button);
            root.setContentPane(surface);
            parent.add(root);
            root.setSize(100,100);
            root.doLayout();
            surface.setSize(100,100);
            surface.doLayout();
            root.addNotify();
            try
            {
                parent.repaints = 0;
                surface.paintImmediately(0,0,100,100);
                assertEquals(1,parent.repaints);
                parent.repaints = 0;
                button.paintImmediately(0,0,20,20);
                assertEquals(1,parent.repaints);
            }
            finally { root.removeNotify(); }
        });
    }

    @Test public void topLevelClearMustStayPrivateUntilHierarchyFinishes() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            BufferedImage screen = new BufferedImage(12,12,BufferedImage.TYPE_INT_ARGB);
            screen.setRGB(6,6,0xffff0000);
            Graphics2D target = screen.createGraphics();
            int[] observedDuringPaint = {0};
            Consumer<Graphics2D> hierarchy = g -> {
                // The installed JDK's Window.paint starts with this operation for !isOpaque().
                Graphics2D clear = (Graphics2D) g.create();
                try
                {
                    clear.setComposite(AlphaComposite.Src);
                    clear.setColor(new Color(0,0,0,0));
                    clear.fillRect(0,0,12,12);
                }
                finally { clear.dispose(); }
                observedDuringPaint[0] = screen.getRGB(6,6);
                g.setColor(Color.GREEN);
                g.fillRect(6,6,1,1);
            };
            try
            {
                // Reproduce the old path: inner surface buffering cannot undo the earlier clear.
                hierarchy.accept(target);
                assertEquals(0,observedDuringPaint[0]);
                assertEquals(0xff00ff00,screen.getRGB(6,6));
                screen.setRGB(6,6,0xffff0000);
                new WindowPresentation().paint(target,12,12,hierarchy);
                assertEquals("Previous completed frame must remain visible during painting",
                    0xffff0000,observedDuringPaint[0]);
                assertEquals(0xff00ff00,screen.getRGB(6,6));
                assertEquals(0,screen.getRGB(5,5));
            }
            finally { target.dispose(); }
        });
    }

    @Test public void fixedFramesAndNewPublicationsNeverExposeAnIntermediateClear() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            surface.setSize(20,20);
            JButton header = new JButton("Close");
            surface.add(header);
            surface.doLayout();
            BufferedImage[] completed = {model(5,Color.RED)};
            surface.modelPainter = g -> g.drawImage(completed[0],0,0,null);
            WindowPresentation presentation = new WindowPresentation();
            BufferedImage screen = new BufferedImage(20,20,BufferedImage.TYPE_INT_ARGB);
            Graphics2D target = screen.createGraphics();
            try
            {
                for (boolean nativeOpaque : new boolean[]{false,true})
                    for (int opacity : new int[]{100,50,0})
                    {
                        surface.opacity = opacity;
                        completed[0] = model(5,Color.RED);
                        Consumer<Graphics2D> hierarchy = g -> {
                            if (!nativeOpaque)
                            {
                                g.setComposite(AlphaComposite.Src);
                                g.setColor(new Color(0,0,0,0));
                                g.fillRect(0,0,20,20);
                                g.setComposite(AlphaComposite.SrcOver);
                            }
                            surface.paint(g);
                        };
                        presentation.paint(target,20,20,hierarchy);
                        BufferedImage previous = copy(screen);
                        for (int i = 0; i < 100; i++)
                        {
                            if (i >= 50) completed[0] = model(5 + i % 2,i % 2 == 0 ? Color.RED : Color.GREEN);
                            BufferedImage last = previous;
                            presentation.paint(target,20,20,g -> {
                                // A private clear must not alter any already-presented model/UI pixel.
                                g.setComposite(AlphaComposite.Clear);
                                g.fillRect(0,0,20,20);
                                g.setComposite(AlphaComposite.SrcOver);
                                hierarchy.accept(g);
                                assertPixelsEqual(last,screen);
                            });
                            if (i < 50) assertPixelsEqual(previous,screen);
                            int modelX = i < 50 ? 5 : 5 + i % 2;
                            assertEquals(255,screen.getRGB(modelX,15) >>> 24);
                            previous = copy(screen);
                        }
                    }
            }
            finally { target.dispose(); }
        });
    }

    @Test public void partialDamageResizeAndFailedPaintRetainCompletedPixels() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            WindowPresentation presentation = new WindowPresentation();
            BufferedImage screen = new BufferedImage(40,40,BufferedImage.TYPE_INT_ARGB);
            Graphics2D target = screen.createGraphics();
            try
            {
                presentation.paint(target,40,40,g -> { g.setColor(Color.RED); g.fillRect(0,0,40,40); });
                target.setClip(10,10,10,10);
                presentation.paint(target,40,40,g -> { g.setColor(Color.GREEN); g.fillRect(0,0,40,40); });
                assertEquals(0xffff0000,screen.getRGB(0,0));
                assertEquals(0xff00ff00,screen.getRGB(15,15));
                BufferedImage previous = copy(screen);
                try
                {
                    presentation.paint(target,40,40,g -> { g.fillRect(0,0,40,40); throw new IllegalStateException("paint failed"); });
                    fail("Expected paint failure");
                }
                catch (IllegalStateException expected) { assertEquals("paint failed",expected.getMessage()); }
                assertPixelsEqual(previous,screen);
                target.setClip(null);
                for (int size : new int[]{20,40,10,40})
                {
                    presentation.paint(target,size,size,g -> { g.setColor(Color.BLUE); g.fillRect(size-1,size-1,1,1); });
                    assertEquals(0,screen.getRGB(0,0));
                    assertEquals(0xff0000ff,screen.getRGB(size-1,size-1));
                }
            }
            finally { target.dispose(); }
        });
    }

    private static BufferedImage model(int x, Color color)
    {
        BufferedImage image = new BufferedImage(20,20,BufferedImage.TYPE_INT_ARGB);
        image.setRGB(x,15,color.getRGB());
        image.setRGB(x+5,15,0xff000000); // NPC/black model detail must also retain full alpha.
        return image;
    }

    private static BufferedImage copy(BufferedImage source)
    {
        BufferedImage image = new BufferedImage(source.getWidth(),source.getHeight(),BufferedImage.TYPE_INT_ARGB);
        image.setRGB(0,0,source.getWidth(),source.getHeight(),source.getRGB(0,0,source.getWidth(),source.getHeight(),null,0,source.getWidth()),0,source.getWidth());
        return image;
    }

    private static void assertPixelsEqual(BufferedImage expected, BufferedImage actual)
    {
        assertArrayEquals(expected.getRGB(0,0,expected.getWidth(),expected.getHeight(),null,0,expected.getWidth()),
            actual.getRGB(0,0,actual.getWidth(),actual.getHeight(),null,0,actual.getWidth()));
    }

    private static final class NativeParent extends Container
    {
        int repaints;
        @Override public boolean isShowing() { return true; }
        @Override public void repaint(long delay, int x, int y, int width, int height) { repaints++; }
    }
}

package com.modelpopout;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

public class WindowStackingTest
{
    @Test public void changesApplyImmediatelyToOnlyTheSelectedWindow()
    {
        AtomicBoolean viewer=new AtomicBoolean(),client=new AtomicBoolean();
        assertTrue(WindowStacking.apply(true,() -> true,viewer::set));
        assertTrue(viewer.get());assertFalse(client.get());
        assertTrue(WindowStacking.apply(false,() -> true,viewer::set));
        assertFalse(viewer.get());assertFalse(client.get());
    }

    @Test public void savedPreferenceIsReappliedWhenAWindowIsRecreated()
    {
        AtomicBoolean saved=new AtomicBoolean(true);
        for(int opening=0;opening<3;opening++)
        {
            AtomicBoolean viewer=new AtomicBoolean();
            assertTrue(WindowStacking.apply(saved.get(),() -> true,viewer::set));
            assertEquals(saved.get(),viewer.get());
            if(opening==1) saved.set(false);
        }
    }

    @Test public void unsupportedDesktopRejectsEnablingWithoutCallingTheSetter()
    {
        AtomicInteger calls=new AtomicInteger();
        assertFalse(WindowStacking.apply(true,() -> false,value -> calls.incrementAndGet()));
        assertEquals(0,calls.get());
        assertTrue(WindowStacking.apply(false,() -> false,value -> calls.incrementAndGet()));
        assertEquals(1,calls.get()); // Disabling still attempts to restore normal stacking.
    }

    @Test public void capabilityOrSetterFailureDoesNotEscapeIntoConfigurationHandling()
    {
        assertFalse(WindowStacking.apply(true,() -> {throw new SecurityException();},value -> fail()));
        assertFalse(WindowStacking.apply(true,() -> true,value -> {throw new UnsupportedOperationException();}));
        assertFalse(WindowStacking.apply(false,() -> true,value -> {throw new SecurityException();}));
    }
}

package com.modelpopout;

import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WindowTitleBarTest
{
    static final class Actions implements WindowTitleBar.Actions
    {
        int minimized,closed,maximized,moves;
        Rectangle rectangle=new Rectangle(-900,100,500,400);
        boolean max;
        public void minimize() { minimized++; }
        public void maximize() { maximized++;max=!max; }
        public void close() { closed++; }
        public Rectangle bounds() { return new Rectangle(rectangle); }
        public boolean maximized() { return max; }
        public void move(Rectangle bounds) { moves++;rectangle=bounds; }
    }

    @Test public void buttonsDragAndDoubleClickHaveSeparateTargets() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Actions actions=new Actions();WindowTitleBar bar=new WindowTitleBar(actions);
            bar.minimize.doClick();bar.maximize.doClick();bar.maximize.doClick();bar.close.doClick();
            assertEquals(1,actions.minimized);assertEquals(2,actions.maximized);assertEquals(1,actions.closed);
            assertEquals(0,actions.moves);
            mouse(bar.title,MouseEvent.MOUSE_PRESSED,-800,110,1);
            mouse(bar.title,MouseEvent.MOUSE_DRAGGED,-600,160,1);
            mouse(bar.title,MouseEvent.MOUSE_RELEASED,-600,160,1);
            assertEquals(new Rectangle(-700,150,500,400),actions.rectangle);
            mouse(bar.title,MouseEvent.MOUSE_DRAGGED,500,500,1);assertEquals(1,actions.moves);
            mouse(bar.title,MouseEvent.MOUSE_CLICKED,0,0,2);assertTrue(actions.max);
            mouse(bar.title,MouseEvent.MOUSE_PRESSED,0,0,1);
            mouse(bar.title,MouseEvent.MOUSE_DRAGGED,100,100,1);assertEquals(1,actions.moves);
            for (MouseMotionListener listener:bar.close.getMouseMotionListeners())
                assertNotSame(bar.title.getMouseMotionListeners()[0],listener);
        });
    }

    static void mouse(Component target,int id,int screenX,int screenY,int clicks)
    {
        target.dispatchEvent(new MouseEvent(target,id,0,InputEvent.BUTTON1_DOWN_MASK,10,10,screenX,screenY,clicks,false,MouseEvent.BUTTON1));
    }

    @Test public void chromeIsOpaqueAndModelsCannotCoverItAtEveryOpacity() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface=new ViewerWindow.Surface();
            surface.titleBar=new WindowTitleBar(new Actions());surface.add(surface.titleBar,BorderLayout.NORTH);
            surface.setBorder(BorderFactory.createEmptyBorder(6,6,6,6));surface.setSize(480,300);surface.doLayout();
            surface.titleBar.doLayout();
            surface.modelPainter=g -> {g.setColor(Color.RED);g.fillRect(0,0,480,300);};
            WindowPresentation presentation=new WindowPresentation();
            for (int opacity:new int[]{0,30,50,100})
            {
                surface.opacity=opacity;
                BufferedImage image=new BufferedImage(480,300,BufferedImage.TYPE_INT_ARGB);
                Graphics2D g=image.createGraphics();presentation.paint(g,480,300,surface::paint);g.dispose();
                assertEquals(new Color(38,38,38).getRGB(),image.getRGB(7,7));
                assertEquals(Color.RED.getRGB(),image.getRGB(100,100));
                assertEquals("Resize hit targets must remain opaque even on click-through desktops",255,image.getRGB(0,0)>>>24);
                assertFalse(surface.isOpaque());
            }
        });
    }

    @Test public void chromeImmediateRepaintsAscendToPresentation() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface=new ViewerWindow.Surface();
            surface.titleBar=new WindowTitleBar(new Actions());surface.add(surface.titleBar,BorderLayout.NORTH);
            JRootPane root=new JRootPane();root.setContentPane(surface);ViewerWindow.keepPresentationNonOpaque(root);
            assertTrue(surface.isPaintingOrigin());
            assertFalse(root.isOpaque());assertFalse(root.getLayeredPane().isOpaque());
            assertTrue(surface.titleBar.isOpaque());
        });
    }

    @Test public void virtualDesktopGeometryUsesLogicalCoordinatesAndInsets()
    {
        Rectangle monitor=new Rectangle(-1536,-200,1536,864);
        assertEquals(new Rectangle(-1536,-170,1536,794),WindowGeometry.usable(monitor,new Insets(30,0,40,0)));
        assertTrue(WindowGeometry.titleReachable(new Rectangle(-1400,-100,500,400),monitor));
        assertFalse(WindowGeometry.titleReachable(new Rectangle(4000,200,500,400),monitor));
        Rectangle start=new Rectangle(-1400,-100,500,400);
        assertEquals(new Rectangle(-1300,0,500,400),WindowGeometry.move(start,new Point(-1200,-50),new Point(-1100,50)));
        assertEquals(new Rectangle(-1400,-100,500,400),start);
    }
}

package com.modelpopout;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class WindowTransparencyTest
{
    /** Models the public JDK background setter's equality and alpha-transition conditions. */
    private static final class NativeWindow
    {
        Color background = new Color(0,0,0,0);
        boolean capable, reject;
        final List<Integer> alphas = new ArrayList<>();
        void setBackground(Color next)
        {
            Color previous=background;background=next;alphas.add(next.getAlpha());
            if(previous.equals(next)) return;
            if(previous.getAlpha()==255 && next.getAlpha()<255)
            {
                if(reject) throw new UnsupportedOperationException("Desktop rejected translucency");
                capable=true;
            }
        }
        boolean apply(boolean available)
        {return WindowTransparency.apply(available,() -> capable,() -> background,this::setBackground);}
    }
    @Test public void transparentColorWithLostAlphaConfigurationMustRenegotiateInsteadOfRepeatingNoOp()
    {
        NativeWindow nativeWindow=new NativeWindow();
        assertTrue(nativeWindow.apply(true));
        assertEquals(List.of(255,0),nativeWindow.alphas);assertTrue(nativeWindow.capable);
        assertEquals(0,nativeWindow.background.getAlpha());
        nativeWindow.alphas.clear();nativeWindow.apply(true);
        assertEquals("Healthy configuration must never toggle native opacity",List.of(0),nativeWindow.alphas);
    }
    @Test public void opaqueBackgroundNegotiatesDirectlyAndConfigurationLossCanRecoverRepeatedly()
    {
        NativeWindow nativeWindow=new NativeWindow();nativeWindow.background=Color.BLACK;
        assertTrue(nativeWindow.apply(true));assertEquals(List.of(0),nativeWindow.alphas);
        for(int i=0;i<3;i++)
        {
            nativeWindow.capable=false;nativeWindow.alphas.clear();
            assertTrue(nativeWindow.apply(true));assertEquals(List.of(255,0),nativeWindow.alphas);
        }
    }
    @Test public void unsupportedOrRejectedDesktopFallsBackWithoutClaimingTransparency()
    {
        NativeWindow unavailable=new NativeWindow();
        assertFalse(unavailable.apply(false));assertEquals(List.of(255),unavailable.alphas);
        NativeWindow rejected=new NativeWindow();rejected.reject=true;
        assertFalse(rejected.apply(true));assertEquals(255,rejected.background.getAlpha());
        assertFalse(rejected.capable);
    }
    @Test public void advertisedSupportWithoutAUsableConfigurationMustNotSilentlyLoseAlpha()
    {
        Color[] background={Color.BLACK};
        boolean supported=WindowTransparency.apply(true,() -> false,() -> background[0],next -> background[0]=next);
        assertFalse(supported);assertEquals(255,background[0].getAlpha());
    }
}

import org.junit.runner.*;
import org.junit.runner.notification.*;
public class JavaTestRunner {
    public static void main(String[] names) throws Exception {
        JUnitCore core = new JUnitCore(); int[] skipped = {0};
        core.addListener(new RunListener() { @Override public void testAssumptionFailure(Failure f) { skipped[0]++; } });
        Class<?>[] tests = new Class<?>[names.length];
        for (int i = 0; i < names.length; i++) tests[i] = Class.forName(names[i]);
        Result result = core.run(tests);
        for (Failure f : result.getFailures()) System.out.println(f.getTrace());
        System.out.println("Passed: " + (result.getRunCount()-result.getFailureCount()-skipped[0]) + ", failed: " + result.getFailureCount() + ", skipped: " + skipped[0]);
        if (!result.wasSuccessful()) System.exit(1);
    }
}
